import tidyingUpImage from '../themes/princess/tidying-up.webp'
import writingImage from '../themes/princess/writing.svg'

export type ChoreImageKey = 'tidyingUp' | 'writing'

export const choreImages: Record<ChoreImageKey, string> = {
  tidyingUp: tidyingUpImage,
  writing: writingImage,
}

export type ChoreImageOption = {
  id: '' | ChoreImageKey
  label: string
  image?: string
}

export const choreImageOptions: ChoreImageOption[] = [
  { id: '', label: 'No image' },
  { id: 'tidyingUp', label: 'Tidying up', image: tidyingUpImage },
  { id: 'writing', label: 'Writing', image: writingImage },
]

export const isChoreImageKey = (imageKey: string): imageKey is ChoreImageKey =>
  imageKey in choreImages

export const getChoreImage = (imageKey?: string) => {
  if (!imageKey) return undefined
  return isChoreImageKey(imageKey) ? choreImages[imageKey] : undefined
}

import yoshiEggImage from './YoshiEgg.webp'
import teeniepingImage from './teenieping.webp'

export type RewardImageKey = 'yoshiEgg' | 'teenieping'

export const rewardImages: Record<RewardImageKey, string> = {
  teenieping: teeniepingImage,
  yoshiEgg: yoshiEggImage,
}

export type RewardImageOption = {
  id: '' | RewardImageKey
  label: string
  image?: string
}

export const rewardImageOptions: RewardImageOption[] = [
  { id: '', label: 'No image' },
  { id: 'teenieping', label: 'Teenieping', image: teeniepingImage },
  { id: 'yoshiEgg', label: 'Hatchin Yoshi', image: yoshiEggImage },
]

export const isRewardImageKey = (
  imageKey: string
): imageKey is RewardImageKey => imageKey in rewardImages

export const getRewardImage = (imageKey?: string) => {
  if (!imageKey) return undefined
  if (imageKey === 'pinkPrincess') return teeniepingImage
  return isRewardImageKey(imageKey) ? rewardImages[imageKey] : undefined
}

import { FirebaseAuthentication } from '@capacitor-firebase/authentication'
import { Capacitor } from '@capacitor/core'
import type { User } from 'firebase/auth'
import {
  GoogleAuthProvider,
  onAuthStateChanged,
  signInWithCredential,
  signInWithPopup,
  signOut,
} from 'firebase/auth'
import type { ReactNode } from 'react'
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react'
import { z } from 'zod'
import { auth } from '../firebase'

type AuthContextValue = {
  user: User | null
  loading: boolean
  loginWithGoogle: () => Promise<void>
  logout: () => Promise<void>
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined)

const nativeGoogleSignInResultSchema = z.object({
  credential: z.object({
    idToken: z.string().min(1),
  }),
})

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [user, setUser] = useState<User | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser)
      setLoading(false)
    })

    return unsubscribe
  }, [])

  const loginWithGoogle = useCallback(async () => {
    if (Capacitor.isNativePlatform()) {
      // Use the Capacitor plugin on Android/iOS — avoids WebView popup restrictions
      const result = nativeGoogleSignInResultSchema.parse(
        await FirebaseAuthentication.signInWithGoogle()
      )
      const idToken = result.credential.idToken
      const credential = GoogleAuthProvider.credential(idToken)
      await signInWithCredential(auth, credential)
    } else {
      // Standard web popup flow
      const provider = new GoogleAuthProvider()
      await signInWithPopup(auth, provider)
    }
  }, [])

  const logout = useCallback(async () => {
    await signOut(auth)
  }, [])

  const value = useMemo(
    () => ({
      user,
      loading,
      loginWithGoogle,
      logout,
    }),
    [user, loading, loginWithGoogle, logout]
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

// eslint-disable-next-line react-refresh/only-export-components
export const useAuth = () => {
  const context = useContext(AuthContext)

  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }

  return context
}

