            src={mathsCounterIcon}
            size={ONE_COUNTER_SIZE}
            delay={index * 0.04}
            animationName="large-numbers-pop-in"
          />
        ))
      )}
    </div>
  )

  const renderTenRods = (count: number, color: string) => (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(5, max-content)',
        justifyContent: 'center',
        alignItems: 'flex-end',
        gap: DOT_GAP,
        minHeight: 92,
        width: '100%',
      }}
      aria-hidden="true"
    >
      {count === 0 ? (
        <EmptyCounterHint color={color} fontFamily={theme.fonts.body} />
      ) : (
        Array.from({ length: count }).map((_, index) =>
          renderTenRod(`ten-rod-${index}`, index)
        )
      )}
    </div>
  )

  const renderRegroupedTen = () => (
    <div
      style={{
        minHeight: 142,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        boxSizing: 'border-box',
      }}
      aria-hidden="true"
    >
      {userOnesTens > 0 && renderTenRod('ones-regrouped-ten', 0)}
    </div>
  )

  const counterControl = (
    label: string,
    value: number,
    color: string,
    onPrev: () => void,
    onNext: () => void,
    disablePrev: boolean,
    disableNext: boolean,
    counters: ReactNode
  ) => (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 6,
        width: '100%',
        minWidth: 0,
        borderRadius: 14,
        border: `2px solid ${color}24`,
        background: `${color}10`,
        padding: 8,
        boxSizing: 'border-box',
      }}
    >
      <span
        style={{
          fontFamily: theme.fonts.heading,
          fontSize: 15,
          fontWeight: 800,
          color,
          lineHeight: 1,
        }}
      >
        {label}
      </span>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
