                gap: PLACE_VALUE_PANEL_GAP,
                width: '100%',
                alignItems: 'stretch',
              }}
            >
              {/* Tens Column */}
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  background: `${theme.colors.secondary}12`,
                  borderRadius: 16,
                  padding: 8,
                  border: `2px solid ${theme.colors.secondary}22`,
                  boxSizing: 'border-box',
                }}
              >
                <span
                  style={{
                    fontSize: 18,
                    fontWeight: 'bold',
                    fontFamily: theme.fonts.heading,
                    color: theme.colors.secondary,
                    marginBottom: 6,
                  }}
                >
                  Tens
                </span>

                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 4,
                    marginBottom: 8,
                    width: '100%',
                  }}
                >
                  <StepperButton
                    theme={theme}
                    direction="prev"
                    onClick={() =>
                      setUserTens((value) => Math.max(0, value - 1))
                    }
                    disabled={userTens === 0 || isCorrect}
                    ariaLabel="Remove ten"
                    style={{
                      width: PLACE_VALUE_TENS_STEPPER_WIDTH,
                      minWidth: PLACE_VALUE_TENS_STEPPER_WIDTH,
