import { uiTokens } from '../tokens'

const CALENDAR_URL = 'https://getschoolcalendar-6ujocyt4pq-uc.a.run.app'

const WEEKDAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
const TOTAL_CALENDAR_CELLS = 42

type CalendarDayData = {
  isNonSchoolDay?: boolean
}

const getNonSchoolDayIcon = (season: ReturnType<typeof getSeasonForDate>) => {
  switch (season) {
    case 'spring':
      return princessNonSchoolDaySpringImage
    case 'summer':
      return princessNonSchoolDaySummerImage
    case 'autumn':
      return princessNonSchoolDayAutumnImage
    case 'winter':
    default:
      return princessNonSchoolDayWinterImage
  }
}

const getMondayFirstOffset = (date: Date) => {
  const day = date.getDay()
  return day === 0 ? 6 : day - 1
}

const getClampedMonthDate = (date: Date, monthDelta: number) => {
  const targetYear = date.getFullYear()
  const targetMonth = date.getMonth() + monthDelta
  const targetDay = date.getDate()
  const daysInTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate()

  return new Date(
    targetYear,
    targetMonth,
    Math.min(targetDay, daysInTargetMonth),
    12,
    0,
    0,
    0
  )
}

const isWeekend = (date: Date) => {
  const day = date.getDay()
  return day === 0 || day === 6
}

type SchoolCalendarProps = {
  theme: Theme
}

export default function SchoolCalendar({ theme }: SchoolCalendarProps) {
  const { selectedDateKey, setSelectedDateKey } = useSelectedDate()
  const [events, setEvents] = useState<Record<string, CalendarDayData>>({})
  const [loaded, setLoaded] = useState(false)
  const [viewDate, setViewDate] = useState(() => parseDateKey(selectedDateKey))
  const todayDateKey = getTodayDescriptor().dateKey

  useEffect(() => {
    setViewDate((currentDate) => {
      const selectedDate = parseDateKey(selectedDateKey)
      const sameMonth =
        currentDate.getFullYear() === selectedDate.getFullYear() &&
        currentDate.getMonth() === selectedDate.getMonth()

      return sameMonth ? currentDate : selectedDate
    })
  }, [selectedDateKey])

  useEffect(() => {
    const cached = localStorage.getItem(CACHE_KEY)
    const cachedTs = localStorage.getItem(CACHE_TS_KEY)

    if (cached && cachedTs && Date.now() - Number(cachedTs) < CACHE_TTL_MS) {
      try {
        const parsed = JSON.parse(cached)
        setEvents(parsed)
        setLoaded(true)
        return
      } catch {
        // fall through to fetch
      }
    }

    const controller = new AbortController()

    fetch(CALENDAR_URL, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`${res.status}`)
        return res.json()
      })
      .then((data: Record<string, CalendarDayData>) => {
        setEvents(data)
        setLoaded(true)
        localStorage.setItem(CACHE_KEY, JSON.stringify(data))
        localStorage.setItem(CACHE_TS_KEY, String(Date.now()))
      })
      .catch((err) => {
        if (err.name !== 'AbortError') {
          console.error('Failed to fetch school calendar', err)
          setLoaded(true)
        }
      })

    return () => controller.abort()
  }, [])

  const year = viewDate.getFullYear()
  const month = viewDate.getMonth()
  const daysInMonth = new Date(year, month + 1, 0).getDate()

  const firstDayOffset = getMondayFirstOffset(new Date(year, month, 1))
  const trailingDayOffset = TOTAL_CALENDAR_CELLS - firstDayOffset - daysInMonth

  const monthLabel = viewDate.toLocaleString('default', { month: 'long' })

  const season = useMemo(() => getSeasonForDate(viewDate), [viewDate])
  const schoolIcon = princessSchoolDayImage
  const nonSchoolIcon = getNonSchoolDayIcon(season)

  const isDaySchool = (day: number) => {
    const date = new Date(year, month, day)

    if (isWeekend(date)) return false

    if (loaded) {
      const dateKey = buildDateKey(date)
      const eventData = events[dateKey]
      if (eventData?.isNonSchoolDay) return false
    }

    return true
  }

  const navMonth = (delta: number) => {
    const selectedDate = parseDateKey(selectedDateKey)
    const nextDate = getClampedMonthDate(selectedDate, delta)

    setSelectedDateKey(buildDateKey(nextDate))
    setViewDate(nextDate)
  }

  return (
    <section
      style={{
        height: `${uiTokens.timeExplorerLinkedPanelHeight}px`,
        borderRadius: `${uiTokens.surfaceRadius}px`,
        background: theme.colors.surface,
        padding: '12px 12px 10px',
        border: `3px solid ${theme.colors.accent}`,
        fontFamily: theme.fonts.heading,
        boxSizing: 'border-box',
      }}
    >
      {/* Month nav */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: 8,
        }}
      >
        <button
          type="button"
          onClick={() => navMonth(-1)}
          aria-label="Previous month"
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.15rem',
            cursor: 'pointer',
            padding: 2,
          }}
        >
          ◀
        </button>
        <span
          style={{
            fontWeight: 800,
            fontSize: '1rem',
            color: theme.colors.text,
          }}
        >
          {monthLabel} {year}
        </span>
        <button
          type="button"
          onClick={() => navMonth(1)}
          aria-label="Next month"
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.15rem',
            cursor: 'pointer',
            padding: 2,
          }}
        >
          ▶
        </button>
      </div>

      {/* Grid */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(7, 1fr)',
          gap: 3,
        }}
      >
        {/* Weekday headers */}
        {WEEKDAY_LABELS.map((d) => (
          <div
            key={d}
            style={{
              fontSize: '0.58rem',
              fontWeight: 700,
              color: theme.colors.primary,
              textAlign: 'center',
              paddingBottom: 2,
            }}
          >
            {d}
          </div>
        ))}

        {/* Empty leading cells */}
        {Array.from({ length: firstDayOffset }).map((_, i) => (
          <div
            key={`pad-${i}`}
            style={{
              aspectRatio: '1',
              width: '100%',
            }}
          />
        ))}

        {/* Day cells */}
        {Array.from({ length: daysInMonth }).map((_, i) => {
          const day = i + 1
          const isSchool = isDaySchool(day)
          const dateKey = buildDateKey(new Date(year, month, day))
          const isToday = dateKey === todayDateKey
          const isSelected = dateKey === selectedDateKey
          const icon = isSchool ? schoolIcon : nonSchoolIcon

          return (
            <button
              key={day}
              type="button"
              onClick={() => setSelectedDateKey(dateKey)}
              aria-pressed={isSelected}
              aria-label={`Select ${dateKey}`}
              style={{
                aspectRatio: '1',
                borderRadius: '25%',
                position: 'relative',
                overflow: 'hidden',
                background: isSchool ? `${theme.colors.primary}18` : '#ffffff',
                border: isSelected
                  ? `3px solid ${theme.colors.accent}`
                  : isToday
                    ? `3px solid ${theme.colors.secondary}`
                    : '3px solid transparent',
                boxShadow: isSelected
                  ? `0 0 0 2px ${theme.colors.accent}44`
                  : isToday
                    ? `0 0 0 2px ${theme.colors.secondary}88`
                    : undefined,
                cursor: 'pointer',
                padding: 0,
              }}
            >
              <img
                src={icon}
                alt={isSchool ? 'School' : 'Home'}
                style={{
                  position: 'absolute',
                  inset: 0,
                  width: '100%',
                  height: '100%',
                  objectFit: 'contain',
                  padding: '10%',
                  opacity: 0.75,
                }}
              />
              <span
                style={{
                  position: 'absolute',
                  inset: 0,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '1.2rem',
                  fontWeight: 900,
                  lineHeight: 1,
                  color: isSelected
                    ? theme.colors.accent
                    : isToday
                      ? theme.colors.secondary
                      : theme.colors.text,
                  textShadow: '0 0 3px #fff, 0 0 3px #fff',
                }}
              >
                {day}
              </span>
            </button>
          )
        })}

        {/* Empty trailing cells */}
        {Array.from({ length: trailingDayOffset }).map((_, i) => (
          <div
            key={`trail-${i}`}
            style={{
              aspectRatio: '1',
              width: '100%',
            }}
          />
        ))}
      </div>
    </section>
  )
}

