import { useCallback, useMemo, useRef, useState } from 'react'
import {
  useSelectedDate,
  useSolarTimes,
} from '../../contexts/SelectedDateContext'
import type { Theme } from '../../contexts/ThemeContext'
import { getSunPosition } from '../../lib/solar'
import { getSeason } from '../../lib/seasons'
import {
  buildExplorerInstant,
  getClockTimeForInstant,
  getInitialExplorerClockTime,
} from '../../lib/dayNightExplorer/dayNightExplorerCalendar'
import {
  getExplorerBackgroundBlend,
  getExplorerBackdropColor,
  getImageForTime,
  resolveBackgroundImage,
} from '../../lib/dayNightExplorer/dayNightExplorerBackdrop'
import { formatTime } from '../../lib/dayNightExplorer/dayNightExplorerMath'
import {
  EXPLORER_FOCUS_OPTIONS,
  EXPLORER_CITY_OPTIONS,
  getExplorerCityOption,
  type ExplorerCityId,
  type ExplorerDisplayMode,
  type ExplorerFocusId,
} from '../../lib/dayNightExplorer/dayNightExplorerOptions'
import type { ClockViewModel } from './Clock'
import useExplorerClock from './useExplorerClock'
import useSolarSystem3D from './useSolarSystem3D'

type UseDayNightExplorerModelResult = {
  planet: {
    globeReady: boolean
    canvasRef: ReturnType<typeof useSolarSystem3D>['canvasRef']
    options: typeof EXPLORER_FOCUS_OPTIONS
    activeFocusId: ExplorerFocusId
    onSelect: (focusId: ExplorerFocusId) => void
  }
  clock: ClockViewModel
}

const getYearProgress = (date: Date) => {
  const yearStart = new Date(date.getFullYear(), 0, 1)
  const nextYearStart = new Date(date.getFullYear() + 1, 0, 1)

  return (
    (date.getTime() - yearStart.getTime()) /
    (nextYearStart.getTime() - yearStart.getTime())
  )
}

const getEarthRotationDeg = (minutes: number, seconds: number) => {
  const totalMinutes = ((minutes % 1440) + 1440) % 1440
  const dayProgress = (totalMinutes + seconds / 60) / 1440

  return dayProgress * 360
}

export default function useDayNightExplorerModel(
  theme: Theme
): UseDayNightExplorerModelResult {
  const { selectedDate } = useSelectedDate()
  const season = getSeason(selectedDate)
  const [displayMode, setDisplayMode] =
    useState<ExplorerDisplayMode>('earth-focus')
  const [activeFocusId, setActiveFocusId] = useState<ExplorerFocusId>('earth')
  const [activeCalculationCityId, setActiveCalculationCityId] =
    useState<ExplorerCityId>('amsterdam')

  const calculationCity = getExplorerCityOption(activeCalculationCityId)
  const calculationLocation = calculationCity.location

  const solarTimes = useSolarTimes(calculationLocation)
  const initialClockTime = useMemo(
    () => getInitialExplorerClockTime(calculationLocation),
    [calculationLocation]
  )

  const onUpdateRef = useRef<(minutes: number, seconds: number) => void>(null!)

  const clock = useExplorerClock({
    initialMinutes: initialClockTime.totalMinutes,
    initialSeconds: initialClockTime.seconds,
    onUpdate: useCallback(
      (m: number, s: number) => onUpdateRef.current?.(m, s),
      []
    ),
  })

  const currentInstant = useMemo(
    () =>
      buildExplorerInstant(
        selectedDate,
        clock.minutes,
        clock.seconds,
        calculationLocation
      ),
    [calculationLocation, clock.minutes, clock.seconds, selectedDate]
  )
  const sunPosition = useMemo(
    () => getSunPosition(currentInstant),
    [currentInstant]
  )
  const planetSceneState = useMemo(
    () => ({
      displayMode,
      earthRotationDeg: getEarthRotationDeg(clock.minutes, clock.seconds),
      earthOrbitProgress: getYearProgress(selectedDate),
      activeFocusId,
      cityOptions: EXPLORER_CITY_OPTIONS,
      sunPosition,
      monthLabelFontFamily: theme.fontFamily,
    }),
    [
      activeFocusId,
      clock.minutes,
      clock.seconds,
      displayMode,
      selectedDate,
      sunPosition,
      theme.fontFamily,
    ]
  )

  const { canvasRef, globeReady, updateSceneState } =
    useSolarSystem3D(planetSceneState)

  // Direct visual updates during dragging (bypassing React re-renders)
  onUpdateRef.current = useCallback(
    (nextMinutes: number, nextSeconds: number) => {
      // 1. Digital Clock direct DOM updates
      const formatted = formatTime(nextMinutes)
      if (clock.digitalHourRef.current) {
        clock.digitalHourRef.current.textContent = formatted.h
      }
      if (clock.digitalMinuteRef.current) {
        clock.digitalMinuteRef.current.textContent = formatted.m
      }
      if (clock.digitalSecondRef.current) {
        clock.digitalSecondRef.current.textContent = String(
          Math.floor(nextSeconds)
        ).padStart(2, '0')
      }
      if (clock.digitalAmpmRef.current) {
        clock.digitalAmpmRef.current.textContent = formatted.ampm
      }

      // 2. Planet scene direct updates
      const ephemeralInstant = buildExplorerInstant(
        selectedDate,
        nextMinutes,
        nextSeconds,
        calculationLocation
      )
      const ephemeralSunPosition = getSunPosition(ephemeralInstant)
      updateSceneState({
        displayMode,
        earthRotationDeg: getEarthRotationDeg(nextMinutes, nextSeconds),
        earthOrbitProgress: getYearProgress(selectedDate),
        activeFocusId,
        cityOptions: EXPLORER_CITY_OPTIONS,
        sunPosition: ephemeralSunPosition,
        monthLabelFontFamily: theme.fontFamily,
      })
    },
    [
      activeFocusId,
      calculationLocation,
      displayMode,
      selectedDate,
      clock.digitalHourRef,
      clock.digitalMinuteRef,
      clock.digitalSecondRef,
      clock.digitalAmpmRef,
      theme.fontFamily,
      updateSceneState,
    ]
  )

  const handleFocusSelection = useCallback(
    (focusId: ExplorerFocusId) => {
      if (focusId === 'sun' || focusId === 'earth') {
        // Toggle display mode
        const nextDisplayMode: ExplorerDisplayMode =
          displayMode === 'earth-focus' ? 'solar-focus' : 'earth-focus'
        setDisplayMode(nextDisplayMode)

        // Update active focus id to match the new display mode (sun for solar, earth for earth)
        setActiveFocusId(nextDisplayMode === 'solar-focus' ? 'sun' : 'earth')
        return
      }

      const nextCity = getExplorerCityOption(focusId)
      clock.syncClockTime(
        getClockTimeForInstant(currentInstant, nextCity.location)
      )
      setActiveCalculationCityId(focusId)
      setActiveFocusId(focusId)
    },
    [clock, currentInstant, displayMode]
  )

  const filteredOptions = useMemo(() => {
    // Show Sun icon when in Earth focus (to switch to Solar)
    // Show Earth icon when in Solar focus (to switch to Earth)
    const topId = displayMode === 'earth-focus' ? 'sun' : 'earth'
    return EXPLORER_FOCUS_OPTIONS.filter((option) => {
      if (option.id === 'sun' || option.id === 'earth') {
        return option.id === topId
      }
      return true
    })
  }, [displayMode])

  const formattedTime = formatTime(clock.minutes)
  const activityImage = getImageForTime(clock.minutes, theme.activityImages)
  const explorerBackdropColor = getExplorerBackdropColor(
    clock.minutes,
    solarTimes
  )
  const explorerBackgroundBlend = getExplorerBackgroundBlend(
    clock.minutes,
    solarTimes
  )
  const explorerBaseBackgroundImage = resolveBackgroundImage(
    theme.explorerBackgroundImages,
    explorerBackgroundBlend.base,
    season
  )
  const explorerOverlayBackgroundImage = resolveBackgroundImage(
    theme.explorerBackgroundImages,
    explorerBackgroundBlend.overlay,
    season
  )

  return {
    planet: {
      globeReady,
      canvasRef,
      options: filteredOptions,
      activeFocusId,
      onSelect: handleFocusSelection,
    },
    clock: {
      activityImage,
      explorerBackdropColor,
      explorerBaseBackgroundImage,
      explorerOverlayBackgroundImage,
      overlayOpacity: explorerBackgroundBlend.overlayOpacity,
      isDragging: clock.isDragging,
      handTransition: clock.handTransition,
      hourAngle: clock.hourAngle,
      minuteAngle: clock.minuteAngle,
      secondAngle: clock.secondAngle,
      hoursLabel: formattedTime.h,
      minutesLabel: formattedTime.m,
      seconds: clock.seconds,
      ampm: formattedTime.ampm,
      svgRef: clock.svgRef,
      hourHandRef: clock.hourHandRef,
      minuteHandRef: clock.minuteHandRef,
      secondHandRef: clock.secondHandRef,
      digitalHourRef: clock.digitalHourRef,
      digitalMinuteRef: clock.digitalMinuteRef,
      digitalSecondRef: clock.digitalSecondRef,
      digitalAmpmRef: clock.digitalAmpmRef,
      onPointerDown: clock.handlePointerDown,
      onAdjust: clock.adjustMinutes,
    },
  }
}

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from 'react'
import { explorerUi } from '../../lib/dayNightExplorer/dayNightExplorer.constants'
import {
  getClockAngles,
  normalizeExactTime,
  normalizeMinutes,
} from '../../lib/dayNightExplorer/dayNightExplorerMath'

type ClockHandId = 'hour' | 'minute' | 'second'

type ClockTime = {
  totalMinutes: number
  seconds: number
}

type UseExplorerClockOptions = {
  initialMinutes: number
  initialSeconds: number
  onUpdate?: (minutes: number, seconds: number) => void
}

const DEFAULT_HAND_TRANSITION =
  'transform 0.1s cubic-bezier(0.34, 1.56, 0.64, 1)'

const useExplorerClock = ({
  initialMinutes,
  initialSeconds,
  onUpdate,
}: UseExplorerClockOptions) => {
  const [minutes, setMinutes] = useState(initialMinutes)
  const [seconds, setSeconds] = useState(initialSeconds)
  const [isDragging, setIsDragging] = useState(false)

  const minutesRef = useRef(minutes)
  minutesRef.current = minutes

  const svgRef = useRef<SVGSVGElement>(null)
  const hourHandRef = useRef<SVGGElement>(null)
  const minuteHandRef = useRef<SVGGElement>(null)
  const secondHandRef = useRef<SVGGElement>(null)

  const digitalHourRef = useRef<HTMLSpanElement>(null)
  const digitalMinuteRef = useRef<HTMLSpanElement>(null)
  const digitalSecondRef = useRef<HTMLSpanElement>(null)
  const digitalAmpmRef = useRef<HTMLSpanElement>(null)

  const activeHandRef = useRef<ClockHandId | null>(null)
  const lastAngleRef = useRef(0)
  const exactMinutesRef = useRef(minutes)
  const exactSecondsRef = useRef(seconds)
  const lastRenderedSecondRef = useRef(seconds)
  const pendingUpdateRef = useRef<{ x: number; y: number } | null>(null)
  const rafIdRef = useRef<number | null>(null)
  const lastDragCommitRef = useRef(0)

  const applyHandTransforms = useCallback(
    (nextMinutes: number, nextSeconds: number) => {
      const { minuteAngle, hourAngle, secondAngle } = getClockAngles(
        normalizeMinutes(nextMinutes),
        nextSeconds
      )

      if (hourHandRef.current) {
        hourHandRef.current.style.transform = `rotate(${hourAngle}deg)`
      }
      if (minuteHandRef.current) {
        minuteHandRef.current.style.transform = `rotate(${minuteAngle}deg)`
      }
      if (secondHandRef.current) {
        const previousSecond = lastRenderedSecondRef.current
        const shouldAnimateSecondHand =
          !activeHandRef.current &&
          nextSeconds > previousSecond &&
          nextSeconds - previousSecond <= 1

        secondHandRef.current.style.transition = shouldAnimateSecondHand
          ? DEFAULT_HAND_TRANSITION
          : 'none'
        secondHandRef.current.style.transform = `rotate(${secondAngle}deg)`
        lastRenderedSecondRef.current = nextSeconds
      }

      // External callback for unthrottled visual updates (e.g. globe)
      onUpdate?.(nextMinutes, nextSeconds)
    },
    [onUpdate]
  )

  const commitExplorerTime = useCallback(
    (
      nextMinutes: number,
      nextSeconds: number,
      options?: { force?: boolean }
    ) => {
      const normalized = normalizeExactTime(nextMinutes, nextSeconds)
      exactMinutesRef.current = normalized.minutes
      exactSecondsRef.current = normalized.seconds

      const now = performance.now()
      if (
        !options?.force &&
        now - lastDragCommitRef.current < explorerUi.dragCommitIntervalMs
      ) {
        return normalized
      }

      lastDragCommitRef.current = now
      minutesRef.current = normalized.minutes
      setMinutes(normalized.minutes)
      setSeconds(normalized.seconds)
      return normalized
    },
    []
  )

  const adjustMinutes = useCallback((delta: number) => {
    setMinutes((previousMinutes) => {
      const nextMinutes = previousMinutes + delta
      minutesRef.current = nextMinutes
      exactMinutesRef.current = nextMinutes
      return nextMinutes
    })
  }, [])

  const syncClockTime = useCallback(
    (clockTime: ClockTime) => {
      minutesRef.current = clockTime.totalMinutes
      exactMinutesRef.current = clockTime.totalMinutes
      exactSecondsRef.current = clockTime.seconds
      applyHandTransforms(clockTime.totalMinutes, clockTime.seconds)
      setMinutes(clockTime.totalMinutes)
      setSeconds(clockTime.seconds)
    },
    [applyHandTransforms]
  )

  useEffect(() => {
    exactSecondsRef.current = seconds
  }, [seconds])

  useEffect(() => {
    applyHandTransforms(minutes, seconds)
  }, [applyHandTransforms, minutes, seconds])

  useEffect(() => {
    const timer = setInterval(() => {
      if (activeHandRef.current) {
        return
      }

      const normalized = normalizeExactTime(
        exactMinutesRef.current,
        exactSecondsRef.current + 1
      )

      exactMinutesRef.current = normalized.minutes
      exactSecondsRef.current = normalized.seconds
      minutesRef.current = normalized.minutes
      setMinutes(normalized.minutes)
      setSeconds(normalized.seconds)
    }, 1000)

    return () => clearInterval(timer)
  }, [])

  const getAngle = useCallback((clientX: number, clientY: number) => {
    if (!svgRef.current) {
      return 0
    }

    const rect = svgRef.current.getBoundingClientRect()
    const centerX = rect.left + rect.width / 2
    const centerY = rect.top + rect.height / 2
    const x = clientX - centerX
    const y = clientY - centerY

    let degrees = (Math.atan2(y, x) * 180) / Math.PI
    degrees += 90
    if (degrees < 0) {
      degrees += 360
    }

    return degrees
  }, [])

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<SVGGElement>, hand: ClockHandId) => {
      event.stopPropagation()
      event.currentTarget.setPointerCapture(event.pointerId)
      setIsDragging(true)
      activeHandRef.current = hand
      exactMinutesRef.current = minutesRef.current
      exactSecondsRef.current = seconds
      lastDragCommitRef.current = 0
      lastAngleRef.current = getAngle(event.clientX, event.clientY)
    },
    [getAngle, seconds]
  )

  useEffect(() => {
    const processUpdate = () => {
      if (!activeHandRef.current || !pendingUpdateRef.current) {
        rafIdRef.current = null
        return
      }

      const { x, y } = pendingUpdateRef.current
      const currentAngle = getAngle(x, y)
      let deltaAngle = currentAngle - lastAngleRef.current

      if (deltaAngle > 180) {
        deltaAngle -= 360
      }
      if (deltaAngle < -180) {
        deltaAngle += 360
      }

      let nextMinutes = exactMinutesRef.current
      let nextSeconds = exactSecondsRef.current

      if (activeHandRef.current === 'second') {
        nextSeconds += deltaAngle / 6
      } else {
        let deltaMinutes = 0
        if (activeHandRef.current === 'minute') {
          deltaMinutes = deltaAngle / 6
        }
        if (activeHandRef.current === 'hour') {
          deltaMinutes = deltaAngle * 2
        }
        nextMinutes += deltaMinutes
      }

      const normalized = normalizeExactTime(nextMinutes, nextSeconds)
      exactMinutesRef.current = normalized.minutes
      exactSecondsRef.current = normalized.seconds
      applyHandTransforms(normalized.minutes, normalized.seconds)
      commitExplorerTime(normalized.minutes, normalized.seconds)

      lastAngleRef.current = currentAngle
      pendingUpdateRef.current = null
      rafIdRef.current = requestAnimationFrame(processUpdate)
    }

    const handlePointerMove = (event: PointerEvent) => {
      if (!activeHandRef.current) {
        return
      }

      pendingUpdateRef.current = { x: event.clientX, y: event.clientY }
      if (rafIdRef.current === null) {
        rafIdRef.current = requestAnimationFrame(processUpdate)
      }
    }

    const handlePointerUp = () => {
      commitExplorerTime(exactMinutesRef.current, exactSecondsRef.current, {
        force: true,
      })
      setIsDragging(false)
      activeHandRef.current = null
      pendingUpdateRef.current = null
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current)
        rafIdRef.current = null
      }
    }

    if (isDragging) {
      window.addEventListener('pointermove', handlePointerMove)
      window.addEventListener('pointerup', handlePointerUp)
      window.addEventListener('pointercancel', handlePointerUp)
    }

    return () => {
      window.removeEventListener('pointermove', handlePointerMove)
      window.removeEventListener('pointerup', handlePointerUp)
      window.removeEventListener('pointercancel', handlePointerUp)
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current)
      }
    }
  }, [applyHandTransforms, commitExplorerTime, getAngle, isDragging])

  return {
    minutes,
    seconds,
    isDragging,
    handTransition: isDragging ? 'none' : DEFAULT_HAND_TRANSITION,
    ...getClockAngles(minutes, seconds),
    svgRef,
    hourHandRef,
    minuteHandRef,
    secondHandRef,
    digitalHourRef,
    digitalMinuteRef,
    digitalSecondRef,
    digitalAmpmRef,
    handlePointerDown,
    adjustMinutes,
    syncClockTime,
  }
}

export default useExplorerClock

import { useCallback, useEffect, useRef, useState } from 'react'
import SolarSystem3DManager, {
  type SolarSystemSceneState,
} from './SolarSystem3DManager'

const useSolarSystem3D = (sceneState: SolarSystemSceneState) => {
  const [globeReady, setGlobeReady] = useState(false)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const managerRef = useRef<SolarSystem3DManager>(null)
  const initialSceneStateRef = useRef(sceneState)

  useEffect(() => {
    if (!canvasRef.current) {
      return
    }

    const manager = new SolarSystem3DManager(
      canvasRef.current,
      initialSceneStateRef.current
    )
    managerRef.current = manager
    setGlobeReady(true)

    return () => {
      manager.dispose()
      managerRef.current = null
      setGlobeReady(false)
    }
  }, [])

  const updateSceneState = useCallback(
    (nextSceneState: SolarSystemSceneState) => {
      managerRef.current?.setSceneState(nextSceneState)
    },
    []
  )

  useEffect(() => {
    managerRef.current?.setSceneState(sceneState)
  }, [sceneState])

  return {
    canvasRef,
    globeReady,
    updateSceneState,
  }
}

export default useSolarSystem3D

