import { useEffect, useState, type CSSProperties } from 'react'
import type { Theme } from '../../contexts/ThemeContext'
import StepperButton, { getStepperEdgePositionStyle } from './StepperButton'
import { uiTokens } from '../../tokens'
import starSvgUrl from '../../assets/global/star.svg'
import starNegativeSvgUrl from '../../assets/global/star-negative.svg'

const STAR_DISPLAY_STYLES_ID = 'star-display-styles'
const injectStarDisplayStyles = () => {
  if (document.getElementById(STAR_DISPLAY_STYLES_ID)) return
  const style = document.createElement('style')
  style.id = STAR_DISPLAY_STYLES_ID
  style.textContent = `
    @keyframes star-pop-in {
      0% { transform: scale(0) rotate(-180deg); opacity: 0; }
      60% { transform: scale(1.3) rotate(10deg); opacity: 1; }
      100% { transform: scale(1) rotate(var(--star-rot, 0deg)); opacity: 1; }
    }
    @keyframes star-pop-out {
      0% { transform: scale(1) rotate(var(--star-rot, 0deg)); opacity: 1; }
      100% { transform: scale(0) rotate(45deg); opacity: 0; }
    }
  `
  document.head.appendChild(style)
}

export type StarDisplayProps = {
  count: number
  animate?: boolean
  style?: CSSProperties
  className?: string
  emptyContent?: React.ReactNode
  editable?: boolean
  onChange?: (value: number) => void
  min?: number
  max?: number
  theme?: Theme
}

const CONTROLS_DELAY_MS = 550
const CONTROL_ROW_WIDTH = uiTokens.controlRowWidth

type DensityClass = 'low' | 'medium'

const getDensityClass = (count: number): DensityClass => {
  if (count > 24) return 'medium'
  return 'low'
}

const DENSITY_SIZES = {
  low: { width: 32, gap: 8 },
  medium: { width: 20, gap: 4 },
} satisfies Record<DensityClass, { width: number; gap: number }>

type StarIconProps = {
  size: number
  scale?: number
  rotation?: number
  animationDelay?: number
  animate?: boolean
  assetUrl?: string
  style?: CSSProperties
  className?: string
}

type StarIconStyle = CSSProperties & {
  '--star-rot': string
}

const StarIcon = ({
  size,
  scale = 1,
  rotation = 0,
  animationDelay = 0,
  animate = true,
  assetUrl = starSvgUrl,
  style,
  className,
}: StarIconProps) => {
  const finalSize = size * scale

  const starStyle: StarIconStyle = {
    width: finalSize,
    height: finalSize,
    flexShrink: 0,
    filter: 'drop-shadow(0 2px 0 rgba(0,0,0,0.1))',
    '--star-rot': `${rotation}deg`,
    ...(animate
      ? {
          animation:
            'star-pop-in 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards',
          animationDelay: `${animationDelay}s`,
        }
      : {}),
    ...style,
  }

  return (
    <img
      src={assetUrl}
      alt=""
      className={className}
      style={starStyle}
      aria-hidden="true"
    />
  )
}

const FieldVariant = ({
  count,
  animate = true,
  emptyContent,
  style,
  className,
}: StarDisplayProps) => {
  const displayMagnitude = Math.abs(count)
  const densityClass = getDensityClass(displayMagnitude)
  const { width, gap } = DENSITY_SIZES[densityClass]
  const assetUrl = count < 0 ? starNegativeSvgUrl : starSvgUrl

  // Track previous count for animation direction
  const [prevCount, setPrevCount] = useState(displayMagnitude)
  const [animatingOut, setAnimatingOut] = useState<number[]>([])

  useEffect(() => {
    if (displayMagnitude < prevCount && animate) {
      const removedCount = prevCount - displayMagnitude
      const removedIndices = Array.from(
        { length: removedCount },
        (_, i) => displayMagnitude + i
      )
      setAnimatingOut(removedIndices)
      const timer = setTimeout(() => {
        setAnimatingOut([])
        setPrevCount(displayMagnitude)
      }, 300)
      return () => clearTimeout(timer)
    } else {
      setPrevCount(displayMagnitude)
    }
  }, [displayMagnitude, prevCount, animate])

  const containerStyle: CSSProperties = {
    background: '#f1f5f9',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    padding: '12px',
    minHeight: `${uiTokens.listActionHeight}px`,
    border: '2px dashed #cbd5e1',
    display: 'flex',
    flexWrap: 'wrap',
    alignItems: 'center',
    justifyContent: 'center',
    gap: `${gap}px`,
    ...style,
  }

  if (displayMagnitude === 0 && animatingOut.length === 0) {
    return (
      <div style={containerStyle} className={className}>
        {emptyContent !== undefined ? (
          emptyContent
        ) : (
          <span
            style={{
              opacity: 0.5,
              fontStyle: 'italic',
              color: '#64748b',
              fontSize: '0.9rem',
            }}
          >
            No stars yet...
          </span>
        )}
      </div>
    )
  }

  const displayCount = Math.max(displayMagnitude, prevCount)
  const stars = Array.from({ length: displayCount })

  return (
    <div style={containerStyle} className={className}>
      {stars.map((_, i) => {
        const rot = ((i * 33) % 40) - 20
        const isExiting = animatingOut.includes(i)

        return (
          <StarIcon
            key={i}
            size={width}
            assetUrl={assetUrl}
            rotation={rot}
            animationDelay={animate && !isExiting ? i * 0.03 : 0}
            animate={animate && !isExiting}
            style={
              isExiting
                ? {
                    animation: 'star-pop-out 0.3s ease-out forwards',
                  }
                : undefined
            }
          />
        )
      })}
    </div>
  )
}

const CompactCountVariant = ({
  count,
  style,
  className,
  theme,
}: StarDisplayProps) => {
  const assetUrl = count < 0 ? starNegativeSvgUrl : starSvgUrl

  const containerStyle: CSSProperties = {
    background: '#f1f5f9',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    padding: '12px',
    minHeight: `${uiTokens.listActionHeight}px`,
    border: '2px dashed #cbd5e1',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    ...style,
  }

  return (
    <div
      style={containerStyle}
      className={className}
      role="img"
      aria-label={`${count} stars`}
    >
      <span
        style={{
          color: theme?.colors.primary ?? '#EC4899',
          fontFamily: theme?.fonts.heading,
          fontSize: '2rem',
          fontWeight: 900,
          lineHeight: 1,
        }}
      >
        {count}
      </span>
      <StarIcon size={38} assetUrl={assetUrl} animate={false} />
    </div>
  )
}

const shouldUseCompactValue = (count: number) => Math.abs(count) > 10

const renderEditableValue = ({
  count,
  animate,
  theme,
  className,
}: {
  count: number
  animate: boolean
  theme: Theme
  className?: string
}) => {
  const valueStyle: CSSProperties = {
    width: '100%',
    boxSizing: 'border-box',
  }

  return shouldUseCompactValue(count) ? (
    <CompactCountVariant
      count={count}
      theme={theme}
      className={className}
      style={valueStyle}
    />
  ) : (
    <FieldVariant
      count={count}
      animate={animate}
      className={className}
      style={valueStyle}
    />
  )
}

const StarDisplay = ({
  count,
  animate = true,
  style,
  className,
  emptyContent,
  editable = false,
  onChange,
  min = 1,
  max,
  theme,
}: StarDisplayProps) => {
  const [controlsVisible, setControlsVisible] = useState(false)

  useEffect(() => {
    injectStarDisplayStyles()
  }, [])

  useEffect(() => {
    if (!editable) {
      setControlsVisible(false)
      return
    }
    const timer = setTimeout(() => setControlsVisible(true), CONTROLS_DELAY_MS)
    return () => clearTimeout(timer)
  }, [editable])

  const handleDecrement = () => {
    if (onChange && count > min) onChange(count - 1)
  }

  const handleIncrement = () => {
    if (onChange && (max === undefined || count < max)) onChange(count + 1)
  }

  const showControls = editable && controlsVisible

  if (editable && theme) {
    return (
      <div
        style={{
          position: 'relative',
          width: `${CONTROL_ROW_WIDTH}px`,
          maxWidth: '100%',
          overflow: 'visible',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          ...style,
        }}
        className={className}
      >
        <div
          style={{
            ...getStepperEdgePositionStyle('prev'),
            opacity: showControls ? 1 : 0,
            transition: 'opacity 0.3s ease',
            pointerEvents: showControls ? 'auto' : 'none',
            zIndex: showControls ? 3 : 1,
          }}
        >
          <StepperButton
            theme={theme}
            direction="prev"
            onClick={handleDecrement}
            disabled={count <= min}
            ariaLabel="Decrease star value"
            style={{ position: 'relative', zIndex: 3 }}
          />
        </div>

        <div style={{ width: '100%', minWidth: 0 }}>
          {renderEditableValue({ count, animate, theme })}
        </div>

        <div
          style={{
            ...getStepperEdgePositionStyle('next'),
            opacity: showControls ? 1 : 0,
            transition: 'opacity 0.3s ease',
            pointerEvents: showControls ? 'auto' : 'none',
            zIndex: showControls ? 3 : 1,
          }}
        >
          <StepperButton
            theme={theme}
            direction="next"
            onClick={handleIncrement}
            disabled={max !== undefined && count >= max}
            ariaLabel="Increase star value"
            style={{ position: 'relative', zIndex: 3 }}
          />
        </div>
      </div>
    )
  }

  return (
    <FieldVariant
      count={count}
      animate={animate}
      emptyContent={emptyContent}
      style={style}
      className={className}
    />
  )
}

export default StarDisplay

import { useState, useMemo, useRef, useEffect, useCallback } from 'react'
import type { Theme } from '../../contexts/ThemeContext'
import { uiTokens } from '../../tokens'
import starSvgUrl from '../../assets/global/star.svg'

type StarInfoBoxProps = {
  theme: Theme
  totalStars: number
}

// Animation timing constants
const PHASE_DURATION = 1800 // ms for both swarm out AND gather back
const PAUSE_DURATION = 500 // ms pause between swarm and gather

type StarState = 'hidden' | 'swarming' | 'swarmed' | 'gathering' | 'gathered'
type HeroState = 'hidden' | 'growing' | 'pulsing'
type StarTransition = {
  property: string
  duration: string
  timingFunction: string
}

const STAR_TRANSITIONS: Record<StarState, StarTransition> = {
  hidden: {
    property: 'none',
    duration: '0s',
    timingFunction: 'ease',
  },
  swarming: {
    property: 'transform',
    duration: `${PHASE_DURATION}ms`,
    timingFunction: 'cubic-bezier(0.55, 0, 1, 0.45)',
  },
  swarmed: {
    property: 'none',
    duration: '0s',
    timingFunction: 'ease',
  },
  gathering: {
    property: 'transform',
    duration: `${PHASE_DURATION}ms`,
    timingFunction: 'cubic-bezier(0.55, 0, 1, 0.45)',
  },
  gathered: {
    property: 'transform, opacity',
    duration: '0.05s, 0.05s',
    timingFunction: 'ease, ease',
  },
}

const getStarTransform = (
  starState: StarState,
  targetPos: { x: number; y: number; rot: number }
) => {
  if (starState === 'swarming' || starState === 'swarmed') {
    return `translate(${targetPos.x}px, ${targetPos.y}px) rotate(${targetPos.rot}deg) scale(1)`
  }

  if (starState === 'gathering') {
    return 'translate(0px, 0px) rotate(0deg) scale(1)'
  }

  return `translate(0px, 0px) scale(${starState === 'hidden' ? 0.1 : 0})`
}

const MiniStar = ({
  targetPos,
  starState,
  index,
}: {
  targetPos: { x: number; y: number; rot: number }
  starState: StarState
  index: number
}) => {
  const transition = STAR_TRANSITIONS[starState]
  const opacity = starState === 'hidden' || starState === 'gathered' ? 0 : 1

  return (
    <div
      style={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        width: '14px',
        height: '14px',
        marginTop: '-7px',
        marginLeft: '-7px',
        transform: getStarTransform(starState, targetPos),
        transitionProperty: transition.property,
        transitionDuration: transition.duration,
        transitionTimingFunction: transition.timingFunction,
        opacity,
        transitionDelay: starState === 'swarming' ? `${index * 12}ms` : '0ms',
        zIndex: 20,
      }}
    >
      <img
        src={starSvgUrl}
        alt=""
        style={{ width: '100%', height: '100%', display: 'block' }}
        aria-hidden="true"
      />
    </div>
  )
}

const StarInfoBox = ({ theme, totalStars }: StarInfoBoxProps) => {
  const [starStates, setStarStates] = useState<StarState[]>([])
  const [heroState, setHeroState] = useState<HeroState>('hidden')
  const [showResult, setShowResult] = useState(false)
  const [isRunning, setIsRunning] = useState(false)
  const [displayedCount, setDisplayedCount] = useState(totalStars)

  const starsSpawnedRef = useRef(0)
  const hasAnimatedRef = useRef(false)
  const isRunningRef = useRef(false)
  const prevTotalStarsRef = useRef(totalStars)

  // Generate pseudo-random looking positions constrained to fit within the box
  const starPositions = useMemo(() => {
    return Array.from({ length: 50 }, (_, i) => {
      const goldenAngle = 137.508
      const angle = i * goldenAngle
      // Smaller radius to fit within the component frame
      const baseRadius = 30 + i * 1.2
      const radiusVariation = Math.sin(i * 0.7) * 8 + Math.cos(i * 1.3) * 5
      const radius = Math.min(baseRadius + radiusVariation, 70) // Cap the radius
      const rot = (i * 47 + Math.sin(i * 2.1) * 180) % 360

      return {
        x: Math.cos((angle * Math.PI) / 180) * radius,
        y: Math.sin((angle * Math.PI) / 180) * radius,
        rot: rot,
      }
    })
  }, [])

  const runAnimation = useCallback((targetCount: number) => {
    if (isRunningRef.current) return

    isRunningRef.current = true
    setIsRunning(true)
    setShowResult(false)
    setHeroState('hidden')
    starsSpawnedRef.current = 0

    const visualCount = Math.max(0, Math.min(targetCount, 50))

    // Initialize all stars as hidden
    setStarStates(Array(visualCount).fill('hidden'))

    // Phase 1: Spawn stars one by one (they swarm outward)
    const spawnInterval = setInterval(() => {
      starsSpawnedRef.current += 1
      const spawned = starsSpawnedRef.current

      setStarStates((prev) => {
        const next = [...prev]
        if (spawned <= visualCount) {
          next[spawned - 1] = 'swarming'
        }
        return next
      })

      if (spawned >= visualCount) {
        clearInterval(spawnInterval)

        // After swarm animation completes, mark as swarmed
        setTimeout(() => {
          setStarStates(Array(visualCount).fill('swarmed'))

          // Phase 2: After pause, start gathering
          setTimeout(() => {
            setHeroState('growing')
            setStarStates(Array(visualCount).fill('gathering'))

            // Phase 3: After gather completes, stars have merged
            setTimeout(() => {
              setStarStates(Array(visualCount).fill('gathered'))
              setHeroState('pulsing')
              setShowResult(true)
              setDisplayedCount(targetCount)
              isRunningRef.current = false
              setIsRunning(false)
            }, PHASE_DURATION + 100)
          }, PAUSE_DURATION)
        }, PHASE_DURATION)
      }
    }, 35)
  }, [])

  // Trigger animation when totalStars changes OR on initial mount
  useEffect(() => {
    // Skip animation if totalStars is 0 (data not loaded yet)
    if (totalStars === 0) {
      hasAnimatedRef.current = true
      prevTotalStarsRef.current = 0
      isRunningRef.current = false
      setDisplayedCount(0)
      setHeroState('pulsing')
      setShowResult(true)
      setStarStates([])
      setIsRunning(false)
      return
    }

    if (totalStars !== prevTotalStarsRef.current) {
      prevTotalStarsRef.current = totalStars
      hasAnimatedRef.current = true
      runAnimation(totalStars)
    } else if (!hasAnimatedRef.current) {
      // Initial page visit with data ready - run animation
      hasAnimatedRef.current = true
      prevTotalStarsRef.current = totalStars
      runAnimation(totalStars)
    }
  }, [runAnimation, totalStars])

  const handleClick = () => {
    if (!isRunning) {
      runAnimation(totalStars)
    }
  }

  return (
    <section
      className="relative z-10 transform text-center transition-transform hover:scale-[1.02]"
      style={{
        backgroundColor: theme.colors.surface,
        boxShadow: `0 8px 0 ${theme.colors.accent}, 0 10px 30px -10px ${theme.colors.primary}40`,
        border: `5px solid ${theme.colors.primary}`,
        borderRadius: `${uiTokens.surfaceRadius}px`,
        height: '180px',
        overflow: 'hidden',
        cursor: 'pointer',
      }}
      onClick={handleClick}
    >
      {/* Animation Container */}
      <div
        style={{
          position: 'relative',
          width: '100%',
          height: '100%',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          gap: `${uiTokens.actionRowGap}px`,
        }}
      >
        {/* Mini Stars */}
        {starStates.map((state, i) => (
          <MiniStar
            key={i}
            index={i}
            targetPos={starPositions[i]}
            starState={state}
          />
        ))}

        {/* Hero Star - grows during gathering */}
        <div
          style={{
            position: 'relative',
            width: '100px',
            height: '100px',
            flexShrink: 0,
            zIndex: 10,
            opacity: heroState === 'hidden' ? 0 : 1,
            transform: heroState === 'hidden' ? 'scale(0)' : 'scale(1)',
            transition:
              heroState === 'growing'
                ? `opacity ${PHASE_DURATION * 0.3}ms ease-out, transform ${PHASE_DURATION}ms cubic-bezier(0.55, 0, 1, 0.45)`
                : 'none',
            animation:
              heroState === 'pulsing'
                ? 'pulse-soft 3s infinite ease-in-out'
                : 'none',
          }}
        >
          <img
            src={starSvgUrl}
            alt=""
            style={{ width: '100%', height: '100%', display: 'block' }}
            aria-hidden="true"
          />
        </div>

        {/* Result Number - to the right of the star */}
        {showResult && (
          <div
            style={{
              position: 'relative',
              zIndex: 20,
              fontSize: '52px',
              fontWeight: 900,
              color: theme.colors.primary,
              textShadow: `2px 2px 0px ${theme.colors.accent}`,
              animation:
                'reveal-pop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards',
              fontFamily: theme.fonts.heading,
            }}
          >
            {displayedCount}
          </div>
        )}
      </div>

      {/* Keyframe animations injected via style tag */}
      <style>{`
        @keyframes reveal-pop {
          0% { transform: scale(0); opacity: 0; }
          60% { transform: scale(1.5); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        @keyframes pulse-soft {
          0%, 100% { filter: drop-shadow(0 0 10px #fbbf2480); transform: scale(1); }
          50% { filter: drop-shadow(0 0 25px #fbbf24cc); transform: scale(1.05); }
        }
      `}</style>
    </section>
  )
}

