import { useCallback, useEffect, useState } from 'react'
import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  serverTimestamp,
  updateDoc,
} from 'firebase/firestore'
import { db } from '../firebase'
import { useAuth } from '../auth/AuthContext'
import { useActiveChild } from '../contexts/ActiveChildContext'
import { THEME_ID_LOOKUP, isThemeId, type ThemeId } from '../ui/themeOptions'
import {
  childSnapshotDataSchema,
  type ChildProfile,
  type ChildUpdatableFields,
} from './types'
import { mergeMissingTitleDrafts } from './dailyTaskState'
import { useUserCollection } from './useUserCollection'

export function useChildren() {
  const { user } = useAuth()
  const { activeChildId, setActiveChild, clearActiveChild } = useActiveChild()
  const [nameDrafts, setNameDrafts] = useState<Record<string, string>>({})

  const mapChildDocument = useCallback((id: string, data: unknown) => {
    const parsed = childSnapshotDataSchema.safeParse(data)
    if (!parsed.success) {
      console.warn('Skipping invalid child snapshot', {
        id,
        issues: parsed.error.issues,
      })
      return null
    }

    const childData = parsed.data
    const themeId = childData.themeId
    const normalizedThemeId =
      themeId && isThemeId(themeId) ? themeId : undefined

    return {
      id,
      displayName: childData.displayName,
      avatarToken: childData.avatarToken,
      totalStars: childData.totalStars,
      themeId: normalizedThemeId,
      testFailureModeEnabled: childData.testFailureModeEnabled,
      createdAt: childData.createdAt?.toDate?.(),
    }
  }, [])

  const handleChildren = useCallback((nextChildren: ChildProfile[]) => {
    setNameDrafts((prev) =>
      mergeMissingTitleDrafts(
        prev,
        nextChildren.map((child) => ({
          id: child.id,
          title: child.displayName,
        }))
      )
    )
  }, [])

  const clearChildren = useCallback(() => setNameDrafts({}), [])

  const children = useUserCollection({
    userId: user?.uid,
    collectionName: 'children',
    orderByField: 'createdAt',
    errorMessage: 'Failed to subscribe to children',
    mapDocument: mapChildDocument,
    onItems: handleChildren,
    onClear: clearChildren,
  })

  // ── Generic field update ──
  const updateChildField = async (id: string, field: ChildUpdatableFields) => {
    if (!user) return
    try {
      await updateDoc(
        doc(collection(db, 'users', user.uid, 'children'), id),
        field
      )
    } catch (error) {
      console.error('Failed to update child profile', error)
    }
  }

  // ── Name draft helpers ──
  const setNameDraft = (childId: string, value: string) =>
    setNameDrafts((prev) => ({ ...prev, [childId]: value }))

  const commitDisplayName = (childId: string, value: string) => {
    const trimmed = value.trim()
    if (trimmed.length > 0 && trimmed.length <= 40) {
      updateChildField(childId, { displayName: trimmed })
      return
    }
    const saved = children.find((child) => child.id === childId)
    if (saved) {
      setNameDrafts((prev) => ({ ...prev, [childId]: saved.displayName }))
    }
  }

  // ── Theme change ──
  const changeTheme = (child: ChildProfile, nextThemeId: ThemeId) => {
    if ((child.themeId || 'princess') === nextThemeId) return

    const avatarToken = THEME_ID_LOOKUP.get(nextThemeId)?.emoji || '👤'
    updateChildField(child.id, { themeId: nextThemeId, avatarToken })

    if (child.id === activeChildId) {
      setActiveChild({ id: child.id, themeId: nextThemeId })
    }
  }

  // ── Create ──
  const createChild = async () => {
    if (!user) return
    await addDoc(collection(db, 'users', user.uid, 'children'), {
      displayName: '',
      avatarToken: THEME_ID_LOOKUP.get('princess')?.emoji || '👤',
      themeId: 'princess',
      totalStars: 0,
      testFailureModeEnabled: true,
      createdAt: serverTimestamp(),
    })
  }

  // ── Delete ──
  const deleteChild = async (id: string) => {
    if (!user) return
    await deleteDoc(doc(collection(db, 'users', user.uid, 'children'), id))
    if (id === activeChildId) clearActiveChild()
  }

  // ── Select ──
  const selectChild = (childId: string) => {
    const child = children.find((c) => c.id === childId)
    if (child) {
      setActiveChild({ id: child.id, themeId: child.themeId || 'princess' })
    }
  }

  // ── Auto-select first child if none active ──
  useEffect(() => {
    if (children.length > 0) {
      const isCurrentActive =
        activeChildId && children.some((c) => c.id === activeChildId)
      if (!isCurrentActive) {
        setActiveChild({
          id: children[0].id,
          themeId: children[0].themeId || 'princess',
        })
      }
    }
  }, [children, activeChildId, setActiveChild])

  return {
    children,
    nameDrafts,
    setNameDraft,
    commitDisplayName,
    updateChildField,
    changeTheme,
    createChild,
    deleteChild,
    selectChild,
  }
}

import { completeTaskAndAwardStars } from '../lib/starActions'
import { celebrateSuccess } from '../lib/celebrate'
import {
  calculateAwardTaskPatch,
  calculateNextDinnerBiteState,
  calculateWaterToiletStars,
} from '../lib/choreLogic'
import {
  getManageDinnerBitesLeft,
  getManageDinnerRemaining,
  getManageToiletStatus,
  getManageWaterLevel,
  isEatingTask,
  isWaterToiletTask,
  type TaskEphemeralState,
  type TaskWithEphemeral,
} from './types'
import { manageTestOutcomePatch, resetManageChorePatch } from './dailyTaskState'

type ChoreActivityItem = TaskWithEphemeral

type UseChoreActivityActionsArgs = {
  user: { uid: string } | null
  activeChildId: string | null
  dateKey: string
  updateEphemeral: (
    taskId: string,
    patch: Partial<TaskEphemeralState>
  ) => Promise<void>
}

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

export const useChoreActivityActions = ({
  user,
  activeChildId,
  dateKey,
  updateEphemeral,
}: UseChoreActivityActionsArgs) => {
  const getCompletionDelta = (item: ChoreActivityItem) => {
    return isWaterToiletTask(item)
      ? calculateWaterToiletStars(
          getManageWaterLevel(item),
          getManageToiletStatus(item)
        )
      : item.starValue
  }

  const applyBite = async (item: ChoreActivityItem) => {
    return applyTaskBite(item)
  }

  const applyTaskBite = async (item: TaskWithEphemeral) => {
    if (!isEatingTask(item)) return false
    const result = calculateNextDinnerBiteState(
      getManageDinnerBitesLeft(item),
      Boolean(item.manageDinnerCompletedAt)
    )
    if (!result) return false

    const startedAt = item.manageDinnerTimerStartedAt
    const elapsed = startedAt ? Math.floor((Date.now() - startedAt) / 1000) : 0
    const frozenRemaining = Math.max(
      0,
      getManageDinnerRemaining(item) - elapsed
    )

    if (!result.isNowComplete) {
      await updateEphemeral(item.id, {
        manageDinnerBitesLeft: result.nextBites,
      })
      return false
    }

    await delay(850)
    const completionPatch = {
      manageDinnerBitesLeft: result.nextBites,
      manageDinnerCompletedAt: Date.now(),
      manageDinnerTimerStartedAt: null,
      manageDinnerRemainingSeconds: frozenRemaining,
    }
    if (user && activeChildId) {
      await completeTaskAndAwardStars({
        userId: user.uid,
        childId: activeChildId,
        taskId: item.id,
        taskCollection: 'chores',
        dateKey,
        delta: item.starValue,
        updates: completionPatch,
        deleteOnComplete: !item.isRepeating,
      })
    } else {
      await updateEphemeral(item.id, completionPatch)
    }
    return true
  }

  const startDinnerTimer = async (item: ChoreActivityItem) => {
    const now = Date.now()
    await updateEphemeral(item.id, { manageDinnerTimerStartedAt: now })
  }

  const expireDinnerTimer = async (item: ChoreActivityItem) => {
    const now = Date.now()
    await updateEphemeral(item.id, {
      manageDinnerTimerStartedAt: null,
      manageDinnerRemainingSeconds: 0,
      manageDinnerCompletedAt: now,
    })
  }

  const resetDinner = async (item: ChoreActivityItem) => {
    return resetTaskDinner(item)
  }

  const resetTaskDinner = (item: TaskWithEphemeral) => {
    if (!isEatingTask(item)) return Promise.resolve()
    return updateEphemeral(item.id, {
      manageDinnerBitesLeft: item.dinnerTotalBites,
      manageDinnerRemainingSeconds: item.dinnerDurationSeconds,
      manageDinnerCompletedAt: null,
      manageDinnerTimerStartedAt: null,
    })
  }

  const completeChore = async (item: ChoreActivityItem) => {
    return completeTaskChore(item)
  }

  const completeTaskChore = async (task: TaskWithEphemeral) => {
    const delta = getCompletionDelta(task)
    const completionPatch = calculateAwardTaskPatch(task, Date.now())
    if (user && activeChildId) {
      const result = await completeTaskAndAwardStars({
        userId: user.uid,
        childId: activeChildId,
        taskId: task.id,
        taskCollection: 'chores',
        dateKey,
        delta,
        updates: completionPatch,
        deleteOnComplete: !task.isRepeating,
      })
      if (result.appliedDelta > 0) celebrateSuccess()
    } else {
      await updateEphemeral(task.id, completionPatch)
    }
  }

  const failChore = async (item: ChoreActivityItem) => {
    const now = Date.now()
    await updateEphemeral(
      item.id,
      manageTestOutcomePatch(item.taskType, now, 'failure')
    )
  }

  const resetChore = (item: ChoreActivityItem) =>
    updateEphemeral(item.id, resetManageChorePatch(item.taskType))

  return {
    applyBite,
    startDinnerTimer,
    expireDinnerTimer,
    resetDinner,
    completeChore,
    failChore,
    resetChore,
  }
}

