    userId: user?.uid,
    collectionName: 'chores',
    errorMessage: 'Failed to subscribe to chores',
    mapDocument: parseChoreDocument,
    normalizeItems: sortChores,
    onClear: clearEphemeral,
  })

  // ── Derived Data ──
  const rawChoreTemplates = rawChores

  useTitleDraftBackfill(rawChoreTemplates, setTaskTitleDrafts)

  const chores = rawChoreTemplates.map((chore) =>
    mergeTaskEphemeral(chore, ephemeral[chore.id])
  )

  const activeChildChores = useMemo(
    () =>
      chores.filter(
        (t) => t.childId === activeChildId && t.title.trim().length > 0
      ),
    [chores, activeChildId]
  )

  const todayChores = useMemo(
    () =>
      activeChildChores.filter((chore) =>
        isScheduledForDay(chore, todayInfo.dayType)
      ),
    [activeChildChores, todayInfo.dayType]
  )

  const availableChores = todayChores
  const completedTodoCount = todayChores.filter((chore) =>
    Boolean(getManageTaskCompletedAt(chore))
  ).length

  const addChoreDocument = async (data: Record<string, unknown>) => {
    if (!user) return
    return await addDoc(collection(db, 'users', user.uid, 'chores'), data)
  }

  // ── Ephemeral State Helpers ──
  const updateEphemeral = (
    taskId: string,
    patch: Partial<TaskEphemeralState>
  ): Promise<void> => {
    setEphemeral((prev) => ({
      ...prev,
      [taskId]: { ...prev[taskId], ...patch },
    }))

    const clearResolvedPatch = () => {
      setEphemeral((prev) => {
        const current = prev[taskId]
        if (!current) return prev

        const remaining = { ...current }
        for (const key of Object.keys(patch) as Array<
          keyof TaskEphemeralState
        >) {
          if (remaining[key] === patch[key]) delete remaining[key]
        }

        const next = { ...prev }
        if (Object.keys(remaining).length === 0) delete next[taskId]
        else next[taskId] = remaining
        return next
      })
    }

    if (!user) {
      clearResolvedPatch()
      return Promise.resolve()
    }

    return updateDoc(doc(db, 'users', user.uid, 'chores', taskId), patch)
      .catch((err) => {
        console.error('Failed to update chore state', err)
        throw err
      })
      .finally(clearResolvedPatch)
  }

  // ── Generic Mutations ──
  const updateTaskField = async (
    taskId: string,
    field: TaskUpdatableFields
  ) => {
    if (!user) return
    await updateDoc(doc(db, 'users', user.uid, 'chores', taskId), field)
  }

  const updateChoreAndTodayTodoField = async (
    taskId: string,
    field: TaskUpdatableFields
  ) => {
    const patch: TaskUpdatableFields = { ...field }
    if (typeof field.dinnerDurationSeconds === 'number') {
      patch.manageDinnerRemainingSeconds = field.dinnerDurationSeconds
    }
    if (typeof field.dinnerTotalBites === 'number') {
      patch.manageDinnerBitesLeft = field.dinnerTotalBites
    }

    await updateTaskField(taskId, patch)
  }

  // ── Title Draft Helpers ──
  const setTaskTitleDraft = (taskId: string, value: string) =>
    setTaskTitleDrafts((prev) => ({ ...prev, [taskId]: value }))

  const commitTaskTitle = (taskId: string, title: string) => {
    const trimmed = title.trim()
    if (trimmed.length > 0 && trimmed.length <= 80) {
      updateTaskField(taskId, { title: trimmed })
    } else {
      const saved = rawChoreTemplates.find((t) => t.id === taskId)
      if (saved)
        setTaskTitleDrafts((prev) => ({ ...prev, [taskId]: saved.title }))
    }
  }

  // ── Creation Handlers ──
  const createChoreTask = async (
    choreType: ChoreType,
    settings: ChoreDocumentSettings = {}
  ): Promise<ChoreRecord | undefined> => {
    if (!user || !activeChildId) return
    const document = buildChoreDocument(activeChildId, choreType, settings)
    const docRef = await addChoreDocument(document)
    if (!docRef) return
    return parseChoreSnapshot(docRef.id, document) ?? undefined
  }

  const createStandardTask = (settings?: ChoreDocumentSettings) =>
    createChoreTask('standard', settings)
  const createEatingTask = (settings?: ChoreDocumentSettings) =>
    createChoreTask('eating', settings)
  const createWaterToiletTask = (settings?: ChoreDocumentSettings) =>
    createChoreTask('watertoiletcheck', settings)

  const createChoreForToday = async (
    choreType: ChoreType,
    settings: ChoreDocumentSettings
  ) => {
    if (!user || !activeChildId) return
    const task = await createChoreTask(choreType, settings)
    return task
  }

  const deleteTask = async (taskId: string) => {
    if (!user) return
    await deleteDoc(doc(db, 'users', user.uid, 'chores', taskId))

    setTaskTitleDrafts((prev) => {
      const next = { ...prev }
      delete next[taskId]
      return next
    })
    setEphemeral((prev) => {
      const next = { ...prev }
      delete next[taskId]
      return next
    })
  }

  const activityActions = useChoreActivityActions({
    user,
    activeChildId,
    dateKey: todayInfo.dateKey,
    updateEphemeral,
  })

  return {
    chores,
    todos: todayChores,
    todayInfo,
    availableChores,
    completedTodoCount,
    taskTitleDrafts,
    setTaskTitleDraft,
    commitTaskTitle,
    updateTaskField,
    updateChoreAndTodayTodoField,
    updateEphemeral,
    createStandardTask,
    createEatingTask,
    createWaterToiletTask,
    createChoreForToday,
    deleteTask,
    ...activityActions,
  }
}

// ── Real-time rewards subscription + all reward mutations ──

import { useCallback, useEffect, useState } from 'react'
import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  onSnapshot,
  serverTimestamp,
  updateDoc,
} from 'firebase/firestore'
import { db } from '../firebase'
import { useAuth } from '../auth/AuthContext'
import { useActiveChild } from '../contexts/ActiveChildContext'
import { redeemReward } from '../lib/starActions'
import {
  childStarsSnapshotDataSchema,
  rewardSnapshotDataSchema,
  type RewardRecord,
  type RewardUpdatableFields,
} from './types'
import { mergeMissingTitleDrafts } from './dailyTaskState'
import { useUserCollection } from './useUserCollection'

export type RewardDocumentSettings = {
  title: string
  costStars: number
  isRepeating: boolean
  imageKey?: string
}

export function useRewards() {
  const { user } = useAuth()
  const { activeChildId } = useActiveChild()
  const [activeChildStars, setActiveChildStars] = useState<number>(0)
  const [titleDrafts, setTitleDrafts] = useState<Record<string, string>>({})

  const mapRewardDocument = useCallback((id: string, data: unknown) => {
    const parsed = rewardSnapshotDataSchema.safeParse(data)
    if (!parsed.success) {
      console.warn('Skipping invalid reward snapshot', {
        id,
        issues: parsed.error.issues,
      })
      return null
    }

    const rewardData = parsed.data
    return {
      id,
      title: rewardData.title,
      costStars: rewardData.costStars,
      isRepeating: rewardData.isRepeating,
      imageKey: rewardData.imageKey,
      createdAt: rewardData.createdAt?.toDate?.(),
    }
  }, [])

  const handleRewards = useCallback((nextRewards: RewardRecord[]) => {
    setTitleDrafts((prev) => mergeMissingTitleDrafts(prev, nextRewards))
  }, [])

  const rewards = useUserCollection({
    userId: user?.uid,
    collectionName: 'rewards',
    orderByField: 'createdAt',
    errorMessage: 'Failed to subscribe to rewards',
    mapDocument: mapRewardDocument,
    onItems: handleRewards,
  })

  // ── Active child star balance subscription ──
  useEffect(() => {
    if (!user || !activeChildId) {
      setActiveChildStars(0)
      return
    }

    const childRef = doc(db, 'users', user.uid, 'children', activeChildId)
    const unsubscribe = onSnapshot(
      childRef,
      (snapshot) => {
        const parsed = childStarsSnapshotDataSchema.safeParse(snapshot.data())
        if (!parsed.success) {
          console.warn('Invalid child star balance snapshot', {
            id: activeChildId,
            issues: parsed.error.issues,
          })
          setActiveChildStars(0)
          return
        }

        setActiveChildStars(parsed.data.totalStars)
      },
      (error) => {
        console.error('Failed to subscribe to child star balance', error)
        setActiveChildStars(0)
      }
    )

    return unsubscribe
  }, [user, activeChildId])

  // ── Generic field update ──
  const updateRewardField = async (
    rewardId: string,
    field: RewardUpdatableFields
  ) => {
    if (!user) return
    try {
      await updateDoc(
        doc(collection(db, 'users', user.uid, 'rewards'), rewardId),
        field
      )
    } catch (error) {
      console.error('Failed to update reward', error)
    }
  }

  // ── Title draft helpers ──
  const setTitleDraft = (rewardId: string, value: string) =>
    setTitleDrafts((prev) => ({ ...prev, [rewardId]: value }))

  const commitTitle = (rewardId: string, title: string) => {
    const trimmed = title.trim()
    if (trimmed.length > 0 && trimmed.length <= 80) {
      updateRewardField(rewardId, { title: trimmed })
      return
    }
    const saved = rewards.find((r) => r.id === rewardId)
    if (saved) {
      setTitleDrafts((prev) => ({ ...prev, [rewardId]: saved.title }))
    }
  }

  // ── Create ──
  const createStandardReward = async (
    settings: RewardDocumentSettings = {
      title: '',
      costStars: 0,
      isRepeating: true,
      imageKey: '',
    }
  ) => {
    if (!user) return
    await addDoc(collection(db, 'users', user.uid, 'rewards'), {
      title: settings.title,
      costStars: Math.max(0, settings.costStars),
      isRepeating: settings.isRepeating,
      imageKey: settings.imageKey ?? '',
      createdAt: serverTimestamp(),
    })
  }

  // ── Give (redeem) reward ──
  const giveReward = async (reward: RewardRecord) => {
    if (!user || !activeChildId) {
      throw new Error('Please select a child from the chores tab first.')
    }

    await redeemReward({
      userId: user.uid,
      childId: activeChildId,
      reward,
    })
  }

  // ── Delete ──
  const deleteReward = async (id: string) => {
    if (!user) return
    await deleteDoc(doc(collection(db, 'users', user.uid, 'rewards'), id))
  }

  return {
    rewards,
    activeChildStars,
    titleDrafts,
    setTitleDraft,
    commitTitle,
    updateRewardField,
    createStandardReward,
    giveReward,
    deleteReward,
  }
}

// Tests subscription + mutations.

import { useCallback, useMemo, useState } from 'react'
import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  runTransaction,
  type DocumentData,
  updateDoc,
} from 'firebase/firestore'
import { db } from '../firebase'
import { useAuth } from '../auth/AuthContext'
import { useActiveChild } from '../contexts/ActiveChildContext'
import { completeTaskAndAwardStars } from '../lib/starActions'
import { celebrateSuccess } from '../lib/celebrate'
import { parseTestSnapshot } from '../lib/choreParser'
import { calculateAwardTaskPatch } from '../lib/choreLogic'
import { buildDefaultTests, buildTestDocument } from './taskDocuments'
import {
  getTestLastActive,
  manageTestOutcomePatch,
  mergeTestEphemeral,
  useEphemeralExpiry,
  useTitleDraftBackfill,
  useTodayInfo,
} from './dailyTaskState'
import {
  sortByCreatedAtThenTitle,
  type TaskEphemeralState,
  type TaskOutcome,
  type TaskUpdatableFields,
  type TestRecord,
  type TestType,
  type TestWithEphemeral,
} from './types'
import { useUserCollection } from './useUserCollection'

const getPersistedAttemptState = (
  test: TestRecord,
  dateKey: string
): Partial<TaskEphemeralState> => {
  if (
    test.lastAttemptDateKey !== dateKey ||
    typeof test.lastAttemptedAt !== 'number'
  ) {
    return {}
  }

  return manageTestOutcomePatch(
    test.taskType,
    test.lastAttemptedAt,
    test.lastAttemptOutcome ?? 'success'
  )
}

export function useTests() {
  const { user } = useAuth()
  const { activeChildId } = useActiveChild()

  const [ephemeral, setEphemeral] = useState<
    Record<string, TaskEphemeralState>
  >({})
  const [testTitleDrafts, setTestTitleDrafts] = useState<
    Record<string, string>
  >({})
  const todayInfo = useTodayInfo()

  const defaultTests = useMemo<TestRecord[]>(() => {
    if (!activeChildId) return []
    return buildDefaultTests(activeChildId)
  }, [activeChildId])

  const parseTestDocument = useCallback(
    (id: string, data: DocumentData) => parseTestSnapshot(id, data),
    []
  )
  const sortTests = useCallback(
    (tests: TestRecord[]) => [...tests].sort(sortByCreatedAtThenTitle),
    []
  )
  const clearEphemeral = useCallback(() => setEphemeral({}), [])
  const rawTests = useUserCollection({
    userId: user?.uid,
    collectionName: 'tests',
    errorMessage: 'Failed to subscribe to tests',
    mapDocument: parseTestDocument,
    normalizeItems: sortTests,
    onClear: clearEphemeral,
  })

  useTitleDraftBackfill(rawTests, setTestTitleDrafts)

  const savedDefaultsByType = new Map<TestType, TestRecord>()
  for (const test of rawTests) {
    if (test.childId !== activeChildId) continue
    if (!savedDefaultsByType.has(test.taskType)) {
      savedDefaultsByType.set(test.taskType, test)
    }
  }

  const defaultSlotTests = defaultTests.map(
    (test) => savedDefaultsByType.get(test.taskType) ?? test
  )
  const defaultSlotIds = new Set(defaultSlotTests.map((test) => test.id))

  const tests = [
    ...defaultSlotTests,
    ...rawTests.filter((test) => !defaultSlotIds.has(test.id)),
  ].map((test) =>
    mergeTestEphemeral(test, {
      ...getPersistedAttemptState(test, todayInfo.dateKey),
      ...ephemeral[test.id],
    })
  )

  const activeChildTests = useMemo(
    () =>
      tests.filter(
        (test) => test.childId === activeChildId && test.title.trim().length > 0
      ),
    [tests, activeChildId]
  )

  const updateEphemeral = (
    testId: string,
    patch: Partial<TaskEphemeralState>
  ) => {
    setEphemeral((prev) => ({
      ...prev,
      [testId]: { ...prev[testId], ...patch },
    }))
  }

  const updateTestField = async (
    testId: string,
    field: TaskUpdatableFields
  ) => {
    if (!user) return
    const defaultTest = defaultTests.find((test) => test.id === testId)
    const testRef = doc(db, 'users', user.uid, 'tests', testId)
    if (defaultTest) {
      await runTransaction(db, async (transaction) => {
        const snapshot = await transaction.get(testRef)
        if (snapshot.exists()) {
          transaction.update(testRef, field)
        } else {
          transaction.set(testRef, {
            ...buildTestDocument(defaultTest.childId, defaultTest.taskType),
            ...field,
          })
        }
      })
      return
    }

    await updateDoc(testRef, field)
  }

  const setTestTitleDraft = (testId: string, value: string) =>
    setTestTitleDrafts((prev) => ({ ...prev, [testId]: value }))

  const commitTestTitle = (testId: string, title: string) => {
    const trimmed = title.trim()
    if (trimmed.length > 0 && trimmed.length <= 80) {
      updateTestField(testId, { title: trimmed })
    } else {
      const saved = rawTests.find((test) => test.id === testId)
      if (saved) {
        setTestTitleDrafts((prev) => ({ ...prev, [testId]: saved.title }))
      }
    }
  }

  const createTest = async (testType: TestType) => {
    if (!user || !activeChildId) return
    await addDoc(
      collection(db, 'users', user.uid, 'tests'),
      buildTestDocument(activeChildId, testType)
    )
  }

  const createMathTest = () => createTest('math')
  const createLargeNumbersTest = () => createTest('large-numbers')
  const createPVTest = () => createTest('positional-notation')
  const createAlphabetTest = () => createTest('alphabet')
  const createSpellingTest = () => createTest('spelling')

  const deleteTest = async (testId: string) => {
    if (!user) return
    await deleteDoc(doc(db, 'users', user.uid, 'tests', testId))
  }

  const persistTestAttempt = async (
    item: TestWithEphemeral,
    attemptedAt: number | null,
    outcome: TaskOutcome | null
  ) => {
    await updateTestField(item.id, {
      lastAttemptedAt: attemptedAt,
      lastAttemptDateKey: attemptedAt ? todayInfo.dateKey : '',
      lastAttemptOutcome: outcome,
    })
  }

  const completeTest = async (item: TestWithEphemeral) => {
    const now = Date.now()
    const patch = calculateAwardTaskPatch(item, now)
    if (user && activeChildId) {
      const defaultTest = defaultTests.find((test) => test.id === item.id)
      const result = await completeTaskAndAwardStars({
        userId: user.uid,
        childId: activeChildId,
        taskId: item.id,
        taskCollection: 'tests',
        dateKey: todayInfo.dateKey,
        delta: item.starValue,
        updates: {
          lastAttemptedAt: now,
          lastAttemptDateKey: todayInfo.dateKey,
          lastAttemptOutcome: 'success',
        },
        initialTaskData: defaultTest
          ? buildTestDocument(defaultTest.childId, defaultTest.taskType)
          : undefined,
        deleteOnComplete: !item.isRepeating,
      })
      updateEphemeral(item.id, patch)
      if (result.appliedDelta > 0) celebrateSuccess()
    } else {
      updateEphemeral(item.id, patch)
    }
  }

  const failTest = async (item: TestWithEphemeral) => {
    const now = Date.now()
    updateEphemeral(
      item.id,
      manageTestOutcomePatch(item.taskType, now, 'failure')
    )
    await persistTestAttempt(item, now, 'failure')
  }

  const resetTest = async (item: TestWithEphemeral) => {
    updateEphemeral(item.id, manageTestOutcomePatch(item.taskType, null, null))
    await persistTestAttempt(item, null, null)
  }

  useEphemeralExpiry(Boolean(user), rawTests, setEphemeral, getTestLastActive)

  return {
    tests,
    todayInfo,
    availableTests: activeChildTests,
    testTitleDrafts,
    setTestTitleDraft,
    commitTestTitle,
    updateTestField,
    updateEphemeral,
    createMathTest,
    createLargeNumbersTest,
    createPVTest,
    createAlphabetTest,
    createSpellingTest,
    deleteTest,
    completeTest,
    failTest,
    resetTest,
  }
}

import { useEffect, useState } from 'react'
import {
  collection,
  onSnapshot,
  orderBy,
  query,
  type DocumentData,
  type OrderByDirection,
} from 'firebase/firestore'
import { db } from '../firebase'

type UseUserCollectionArgs<T> = {
  userId: string | undefined
  collectionName: string
  orderByField?: string
  orderDirection?: OrderByDirection
  errorMessage: string
  mapDocument: (id: string, data: DocumentData) => T | null
  normalizeItems?: (items: T[]) => T[]
  onItems?: (items: T[]) => void
  onClear?: () => void
}

export const useUserCollection = <T>({
  userId,
  collectionName,
  orderByField,
  orderDirection = 'asc',
  errorMessage,
  mapDocument,
  normalizeItems,
  onItems,
  onClear,
}: UseUserCollectionArgs<T>) => {
  const [items, setItems] = useState<T[]>([])

  useEffect(() => {
    if (!userId) {
      setItems([])
      onClear?.()
      return
    }

    const baseCollection = collection(db, 'users', userId, collectionName)
    const source = orderByField
      ? query(baseCollection, orderBy(orderByField, orderDirection))
      : baseCollection

    return onSnapshot(
      source,
      (snapshot) => {
        const mappedItems = snapshot.docs.flatMap((docSnapshot) => {
          const item = mapDocument(docSnapshot.id, docSnapshot.data())
          return item ? [item] : []
        })
        const nextItems = normalizeItems
          ? normalizeItems(mappedItems)
          : mappedItems

        setItems(nextItems)
        onItems?.(nextItems)
      },
      (error) => {
        console.error(errorMessage, error)
        setItems([])
        onClear?.()
      }
    )
  }, [
    collectionName,
    errorMessage,
    mapDocument,
    normalizeItems,
    onClear,
    onItems,
    orderByField,
    orderDirection,
    userId,
  ])

  return items
}

