import { useCallback, useEffect, useRef, useState } from 'react'
import { celebrateSuccess } from '../lib/celebrate'
import {
  MAX_ACTIVITY_MISTAKES,
  type ActivityResult,
} from '../components/ui/ActivityControls'

export type ActivityFeedback = 'idle' | 'correct' | 'wrong'

type UseActivityChallengeArgs = {
  isRunning: boolean
  isCompleted: boolean
  isFailed: boolean
  totalProblems: number
  checkTrigger: number
  canStart: boolean
  onStart: () => void
  onReset: () => void
  onComplete: () => void
  onFail?: () => void
  failureModeEnabled?: boolean
}

const CELEBRATION_DELAY_MS = 1500
const SHAKE_DURATION_MS = 600
const FAILURE_TRANSITION_DELAY_MS = 3000

export const useActivityChallenge = ({
  isRunning,
  isCompleted,
  isFailed,
  totalProblems,
  checkTrigger,
  canStart,
  onStart,
  onReset,
  onComplete,
  onFail,
  failureModeEnabled = true,
}: UseActivityChallengeArgs) => {
  const [problemIndex, setProblemIndex] = useState(0)
  const [retryCount, setRetryCount] = useState(0)
  const [resultHistory, setResultHistory] = useState<ActivityResult[]>([])
  const [isFailurePending, setIsFailurePending] = useState(false)
  const [feedback, setFeedback] = useState<ActivityFeedback>('idle')
  const feedbackTimer = useRef<ReturnType<typeof setTimeout> | null>(null)
  const prevCheckTrigger = useRef(checkTrigger)

  const clearFeedbackTimer = useCallback(() => {
    if (!feedbackTimer.current) return
    clearTimeout(feedbackTimer.current)
    feedbackTimer.current = null
  }, [])

  const isSetup = !isRunning && !isCompleted
  const incorrectCount = resultHistory.filter(
    (result) => result === 'incorrect'
  ).length
  const hasFailedByHistory =
    failureModeEnabled && incorrectCount >= MAX_ACTIVITY_MISTAKES
  const isFailedState = isCompleted && (isFailed || hasFailedByHistory)
  const isSuccessState = isCompleted && !isFailedState
  const isFinished = isSuccessState || isFailedState
  const isCorrect = feedback === 'correct'
  const isWrong = feedback === 'wrong'

  const startNextProblem = useCallback(
    (nextIndex: number, onNextProblem: (index: number) => void) => {
      setProblemIndex(nextIndex)
      onNextProblem(nextIndex)
    },
    []
  )

  const submitAnswer = useCallback(
    (isAnswerCorrect: boolean, onNextProblem: (index: number) => void) => {
      if (feedback !== 'idle' || isFailurePending) return
      clearFeedbackTimer()

      if (isAnswerCorrect) {
        setFeedback('correct')
        celebrateSuccess()
        window.setTimeout(() => {
          setResultHistory((prev) => [...prev, 'correct'])
        }, 120)

        feedbackTimer.current = setTimeout(() => {
          const nextIndex = problemIndex + 1
          if (nextIndex >= totalProblems) {
            onComplete()
          } else {
            startNextProblem(nextIndex, onNextProblem)
          }
        }, CELEBRATION_DELAY_MS)
        return
      }

      setFeedback('wrong')
      if (failureModeEnabled) {
        setResultHistory((prev) => [...prev, 'incorrect'])
      }
      const nextRetryCount = retryCount + 1
      setRetryCount(nextRetryCount)

      if (failureModeEnabled && nextRetryCount >= MAX_ACTIVITY_MISTAKES) {
        setIsFailurePending(true)
        feedbackTimer.current = setTimeout(() => {
          onFail?.()
        }, FAILURE_TRANSITION_DELAY_MS)
        return
      }

      feedbackTimer.current = setTimeout(
        () => setFeedback('idle'),
        SHAKE_DURATION_MS
      )
    },
    [
      clearFeedbackTimer,
      feedback,
      failureModeEnabled,
      isFailurePending,
      onComplete,
      onFail,
      problemIndex,
      retryCount,
      startNextProblem,
      totalProblems,
    ]
  )

  const resetChallenge = useCallback(() => {
    clearFeedbackTimer()
    setProblemIndex(0)
    setRetryCount(0)
    setResultHistory([])
    setIsFailurePending(false)
    setFeedback('idle')
    onReset()
  }, [clearFeedbackTimer, onReset])

  useEffect(() => clearFeedbackTimer, [clearFeedbackTimer])

  useEffect(() => {
    if (isRunning && canStart && problemIndex === 0 && feedback === 'idle') {
      onStart()
    }
  }, [canStart, feedback, isRunning, onStart, problemIndex])

  useEffect(() => {
    if (isSetup) resetChallenge()
  }, [isSetup, resetChallenge])

  const consumeCheckTrigger = useCallback(
    (isAnswerCorrect: boolean, onNextProblem: (index: number) => void) => {
      if (checkTrigger === prevCheckTrigger.current) return
      prevCheckTrigger.current = checkTrigger
      if (isRunning && !isCompleted) {
        submitAnswer(isAnswerCorrect, onNextProblem)
      }
    },
    [checkTrigger, isCompleted, isRunning, submitAnswer]
  )

  return {
    problemIndex,
    retryCount,
    resultHistory: failureModeEnabled
      ? resultHistory
      : resultHistory.filter((result) => result === 'correct'),
    feedback,
    isSetup,
    isFinished,
    isSuccessState,
    isCorrect,
    isWrong,
    submitAnswer,
    consumeCheckTrigger,
    resetFeedback: () => setFeedback('idle'),
  }
}

import { useEffect, useState } from 'react'
import { Capacitor } from '@capacitor/core'
import { uiTokens } from '../tokens'

export const getBrowserFrameHeight = (isNativePlatform: boolean) => {
  if (isNativePlatform || typeof window === 'undefined') {
    return uiTokens.deviceMinHeight
  }

  const outerPadding = 40
  const availableScreenHeight =
    window.screen?.availHeight ?? window.screen?.height
  const visibleViewportHeight =
    window.visualViewport?.height ?? window.innerHeight
  const preferredHeight = availableScreenHeight ?? visibleViewportHeight
  const fittedHeight = Math.max(
    320,
    Math.min(uiTokens.deviceMinHeight, preferredHeight - outerPadding)
  )
  const safeViewportHeight = Math.max(320, visibleViewportHeight - outerPadding)

  return Math.min(fittedHeight, safeViewportHeight)
}

export const useDeviceFrame = () => {
  const isNativePlatform = Capacitor.isNativePlatform()
  const [browserFrameHeight, setBrowserFrameHeight] = useState<number>(() =>
    getBrowserFrameHeight(isNativePlatform)
  )

  useEffect(() => {
    if (isNativePlatform || typeof window === 'undefined') return

    const updateBrowserFrameHeight = () => {
      setBrowserFrameHeight(getBrowserFrameHeight(false))
    }

    window.addEventListener('resize', updateBrowserFrameHeight)
    window.visualViewport?.addEventListener('resize', updateBrowserFrameHeight)

    return () => {
      window.removeEventListener('resize', updateBrowserFrameHeight)
      window.visualViewport?.removeEventListener(
        'resize',
        updateBrowserFrameHeight
      )
    }
  }, [isNativePlatform])

  return { isNativePlatform, browserFrameHeight }
}

import { useEffect, useRef, useState } from 'react'
import { BITE_COOLDOWN_SECONDS } from '../data/types'
import { celebrateSuccess } from '../lib/celebrate'

type UseDinnerCountdownStateArgs = {
  remaining: number
  bitesLeft: number
  isTimerRunning: boolean
  isCompleted: boolean
  biteCooldownSeconds: number
  biteCooldownEndsAt?: number | null
  timerStartedAt?: number | null
  onExpire?: () => void
}

export const useDinnerCountdownState = ({
  remaining,
  bitesLeft,
  isTimerRunning,
  isCompleted,
  biteCooldownSeconds,
  biteCooldownEndsAt,
  timerStartedAt,
  onExpire,
}: UseDinnerCountdownStateArgs) => {
  const [, setTick] = useState(0)
  const [animSlice, setAnimSlice] = useState<number | null>(null)
  const [biteVis, setBiteVis] = useState(false)
  const prevBites = useRef(bitesLeft)
  const now = Date.now()

  const liveRemainingFloat =
    isTimerRunning && timerStartedAt
      ? Math.max(0, remaining - (now - timerStartedAt) / 1000)
      : remaining
  const liveRemaining = Math.floor(liveRemainingFloat)
  const liveCooldown = biteCooldownEndsAt
    ? Math.max(0, (biteCooldownEndsAt - now) / 1000)
    : 0
  const totalCooldownSeconds = biteCooldownSeconds || BITE_COOLDOWN_SECONDS
  const isCoolingDown = liveCooldown > 0
  const isSuccess = isCompleted && bitesLeft <= 0 && !isCoolingDown
  const isTimeout = liveRemaining <= 0 && bitesLeft > 0
  const isFinished = isSuccess || isTimeout
  const isSetup = !isTimerRunning && !isFinished && !isCoolingDown
  const secRot = getSecondHandRotation(isTimerRunning, liveRemaining)

  useEffect(() => {
    const needsTick =
      isTimerRunning || (biteCooldownEndsAt && biteCooldownEndsAt > Date.now())
    if (!needsTick) return

    const interval = window.setInterval(() => setTick((tick) => tick + 1), 100)
    return () => window.clearInterval(interval)
  }, [isTimerRunning, biteCooldownEndsAt])

  useEffect(() => {
    if (isSuccess) celebrateSuccess()
  }, [isSuccess])

  useEffect(() => {
    if (isTimeout) onExpire?.()
  }, [isTimeout, onExpire])

  useEffect(() => {
    if (bitesLeft < prevBites.current) {
      setAnimSlice(bitesLeft)
      setBiteVis(false)
      const showBiteTimer = setTimeout(() => setBiteVis(true), 20)
      const clearBiteTimer = setTimeout(() => setAnimSlice(null), 800)
      prevBites.current = bitesLeft
      return () => {
        clearTimeout(showBiteTimer)
        clearTimeout(clearBiteTimer)
      }
    }
    prevBites.current = bitesLeft
  }, [bitesLeft])

  return {
    animSlice,
    biteVis,
    isSetup,
    isSuccess,
    isTimeout,
    isFinished,
    liveRemaining,
    liveRemainingFloat,
    liveCooldown,
    totalCooldownSeconds,
    secRot,
  }
}

const getSecondHandRotation = (
  isTimerRunning: boolean,
  liveRemaining: number
) => {
  if (!isTimerRunning || liveRemaining <= 0) return 0
  const seconds = liveRemaining % 60 || 60
  return ((Math.ceil(seconds / 2) * 2) / 60) * 180
}

