  imageKey: string
  dinnerDurationMinutes: number
  dinnerTotalBites: number
}

type ChoreTypeOption = {
  type: ChoreType
  label: string
  icon: string
  defaultDraft: ChoreDraft
}

type ChoreCreationFlowProps = {
  theme: Theme
  isSaving: boolean
  onSave: (
    choreType: ChoreType,
    settings: ChoreDocumentSettings
  ) => void | Promise<void>
  onCancel: () => void
