import { useMemo, useState, type CSSProperties } from 'react'
import type { Theme } from '../contexts/ThemeContext'
import ActionTextInput from '../components/ui/ActionTextInput'
import Carousel from '../components/ui/Carousel'
import RepeatControl from '../components/ui/RepeatControl'
import StarDisplay from '../components/ui/StarDisplay'
import { IconActionRow } from '../components/ui/IconActionControls'
import { rewardImageOptions } from '../assets/rewards/assets'
import {
  princessExitIcon,
  princessSaveIcon,
} from '../assets/themes/princess/assets'
import { uiTokens } from '../tokens'
import type { RewardDocumentSettings } from '../data/useRewards'

type RewardDraft = {
  title: string
  imageKey: string
  costStars: number
  isRepeating: boolean
}

type RewardCreationFlowProps = {
  theme: Theme
  isSaving: boolean
  onSave: (settings: RewardDocumentSettings) => void | Promise<void>
  onCancel: () => void
}

const defaultDraft: RewardDraft = {
  title: 'New Reward',
  imageKey: '',
  costStars: 5,
  isRepeating: true,
}

const RewardCreationFlow = ({
  theme,
  isSaving,
  onSave,
  onCancel,
}: RewardCreationFlowProps) => {
  const [draft, setDraft] = useState<RewardDraft>(defaultDraft)

  const carouselItems = useMemo(
    () =>
      rewardImageOptions.map((option) => ({
        id: option.id,
        label: option.label,
        icon: option.image ? (
          <img
            src={option.image}
            alt=""
            className="h-full w-full object-contain"
            aria-hidden="true"
          />
        ) : (
          <span
            aria-hidden="true"
            style={{
              width: '44px',
              height: '44px',
              borderRadius: 14,
              border: `3px dashed ${theme.colors.primary}`,
              display: 'block',
              opacity: 0.55,
            }}
          />
        ),
      })),
    [theme.colors.primary]
  )

  const currentImageIndex = Math.max(
    0,
    rewardImageOptions.findIndex((option) => option.id === draft.imageKey)
  )

  const updateDraft = (patch: Partial<RewardDraft>) => {
    setDraft((current) => ({ ...current, ...patch }))
  }

  const save = () => {
    if (isSaving) return

    const trimmedTitle = draft.title.trim()
    if (trimmedTitle.length === 0) return

    onSave({
      title: trimmedTitle,
      costStars: draft.costStars,
      isRepeating: draft.isRepeating,
      imageKey: draft.imageKey,
    })
  }

  const panelStyle: CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: `${uiTokens.panelStackGap}px`,
  }

  return (
    <div style={panelStyle}>
      <ActionTextInput
        theme={theme}
        label="Reward"
        value={draft.title}
        onChange={(title) => updateDraft({ title })}
        maxLength={80}
        baseColor={theme.colors.secondary}
        inputAriaLabel="Reward name"
        transparent
      />

      <Carousel
        key={draft.imageKey}
        items={carouselItems}
        title="Reward image"
        initialIndex={currentImageIndex}
        onChange={(index) => {
          const selected = rewardImageOptions[index]
          if (!selected || selected.id === draft.imageKey) return
          updateDraft({ imageKey: selected.id })
        }}
      />

      <StarDisplay
        theme={theme}
        count={draft.costStars}
        editable
        min={0}
        max={999}
        onChange={(costStars) => updateDraft({ costStars })}
      />

      <RepeatControl
        theme={theme}
        value={draft.isRepeating}
        onChange={(isRepeating) => updateDraft({ isRepeating })}
        label="Keep available after buying"
        showLabel={false}
        showFeedback={false}
      />

      <IconActionRow
        theme={theme}
        primaryIcon={princessSaveIcon}
        primaryAriaLabel="Save reward"
        onPrimaryClick={save}
        primaryDisabled={isSaving || draft.title.trim().length === 0}
        primaryIconOpacity={isSaving ? 0.55 : 1}
        utilityIcon={princessExitIcon}
        utilityAriaLabel="Discard reward"
        onUtilityClick={onCancel}
        utilityDisabled={isSaving}
      />
    </div>
  )
}

export default RewardCreationFlow

import { useState } from 'react'
import { useActiveChild } from '../contexts/ActiveChildContext'
import { useTheme } from '../contexts/ThemeContext'
import TabContent from '../components/TabContent'
import StandardActionList from '../components/ui/StandardActionList'
import { getSurfaceWidthConstraints } from '../tokens'
import { createRewardDefinitionListRowDescriptor } from '../ui/definitionRowDescriptors'
import { toStandardActionListDescriptor } from '../ui/listDescriptorTypes'
import { useRewards } from '../data/useRewards'
import RewardCreationFlow from './RewardCreationFlow'
import type { RewardRecord } from '../data/types'
import type { RewardDocumentSettings } from '../data/useRewards'

const RewardsPage = () => {
  const { activeChildId } = useActiveChild()
  const { theme } = useTheme()
  const [isRedeeming, setIsRedeeming] = useState(false)
  const [showAddReward, setShowAddReward] = useState(false)
  const [isCreatingReward, setIsCreatingReward] = useState(false)
  const [createRewardError, setCreateRewardError] = useState<string | null>(
    null
  )

  const {
    rewards,
    activeChildStars,
    createStandardReward,
    giveReward,
    deleteReward,
  } = useRewards()

  const handleGiveReward = async (reward: RewardRecord) => {
    setIsRedeeming(true)
    try {
      await giveReward(reward)
    } catch (error) {
      console.error('Failed to give reward', error)
    } finally {
      setIsRedeeming(false)
    }
  }

  const handleDelete = async (id: string) => {
    try {
      await deleteReward(id)
    } catch (error) {
      console.error('Failed to delete reward', error)
    }
  }

  const handleCreateReward = async (settings: RewardDocumentSettings) => {
    if (isCreatingReward) return

    setIsCreatingReward(true)
    setCreateRewardError(null)
    try {
      await createStandardReward(settings)
      setShowAddReward(false)
    } catch (error) {
      console.error('Failed to create reward', error)
      setCreateRewardError('Could not save reward.')
    } finally {
      setIsCreatingReward(false)
    }
  }

  const rewardListDescriptor = toStandardActionListDescriptor(
    createRewardDefinitionListRowDescriptor({
      theme,
      activeChildId,
      activeChildStars,
      isRedeeming,
      handleGiveReward,
    })
  )

  return (
    <TabContent theme={theme} title="Rewards">
      <div
        className="mx-auto flex w-full flex-col"
        style={{
          ...getSurfaceWidthConstraints(),
          paddingBottom: '96px',
        }}
      >
        {createRewardError && (
          <div
            className="mb-6 rounded-2xl px-4 py-3 text-center text-sm font-bold"
            style={{
              background: `${theme.colors.secondary}20`,
              color: theme.colors.text,
              border: `2px solid ${theme.colors.secondary}`,
            }}
          >
            {createRewardError}
          </div>
        )}
        <StandardActionList
          theme={theme}
          items={rewards}
          getKey={(reward) => reward.id}
          {...rewardListDescriptor}
          hideEdit
          onDelete={(reward) => handleDelete(reward.id)}
          addLabel="New Reward"
          onAdd={() => setShowAddReward(true)}
          addDisabled={isCreatingReward}
          inlineNewRow={
            showAddReward ? (
              <RewardCreationFlow
                theme={theme}
                isSaving={isCreatingReward}
                onSave={handleCreateReward}
                onCancel={() => {
                  setCreateRewardError(null)
                  setShowAddReward(false)
                }}
              />
            ) : undefined
          }
          emptyState={
            <div className="rounded-3xl bg-black/10 p-6 text-center text-lg font-bold">
              No rewards yet.
            </div>
          }
        />
      </div>
    </TabContent>
  )
}

export default RewardsPage

