import { useEffect, useRef, type CSSProperties } from 'react'
import { Outlet, useLocation } from 'react-router-dom'
import { useTheme } from '../contexts/ThemeContext'
import { getTabIdForPath, getTabIndex } from '../lib/tabNavigation'
import { uiTokens } from '../tokens'
import BottomNav from '../components/ui/BottomNav'
import { AppDeviceFrame } from '../components/AppDeviceFrame'
import { useDeviceFrame } from '../hooks/useDeviceFrame'

const TAB_TRANSITION_MS = uiTokens.tabTransitionMs

type TabTransitionStyle = CSSProperties & {
  '--msq-tab-enter-transform': string
}

const AnimatedTabLayout = () => {
  const { theme } = useTheme()
  const location = useLocation()
  const { isNativePlatform, browserFrameHeight } = useDeviceFrame()
  const previousPathRef = useRef(location.pathname)

  const activeTabId = getTabIdForPath(location.pathname)
  const incomingDirection = getTabTransitionDirection(
    previousPathRef.current,
    location.pathname
  )

  useEffect(() => {
    previousPathRef.current = location.pathname
  }, [location.pathname])

  const incomingTransform = `translate3d(${incomingDirection * 18}px, 0, 0)`
  const tabTransitionStyle: TabTransitionStyle = {
    animation: `msq-tab-enter ${TAB_TRANSITION_MS}ms ease forwards`,
    '--msq-tab-enter-transform': incomingTransform,
    willChange: 'opacity, transform',
  }

  return (
    <AppDeviceFrame
      theme={theme}
      isNativePlatform={isNativePlatform}
      browserFrameHeight={browserFrameHeight}
    >
      <div className="relative min-h-0 flex-1 overflow-hidden">
        <div
          key={location.pathname}
          className="h-full w-full min-w-0"
          style={tabTransitionStyle}
        >
          <Outlet />
        </div>
      </div>

      {activeTabId && <BottomNav theme={theme} activeTabId={activeTabId} />}
    </AppDeviceFrame>
  )
}

export default AnimatedTabLayout

const getTabTransitionDirection = (
  previousPath: string,
  nextPath: string
): 1 | -1 => {
  if (previousPath === nextPath) return 1

  const previousTabId = getTabIdForPath(previousPath)
  const nextTabId = getTabIdForPath(nextPath)
  const previousIndex = previousTabId ? getTabIndex(previousTabId) : -1
  const nextIndex = nextTabId ? getTabIndex(nextTabId) : -1

  return previousIndex !== -1 && nextIndex !== -1 && nextIndex < previousIndex
    ? -1
    : 1
}

import { Navigate, Outlet, useLocation } from 'react-router-dom'
import { useAuth } from '../auth/AuthContext'

const ProtectedRoute = () => {
  const { user, loading } = useAuth()
  const location = useLocation()

  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-slate-950 text-slate-200">
        <span className="text-lg font-medium">Checking your session…</span>
      </main>
    )
  }

  if (!user) {
    return <Navigate to="/login" replace state={{ from: location }} />
  }

  return <Outlet />
}

export default ProtectedRoute

export type ChoreStage = 'setup' | 'activity' | 'completed'

export type ChoreModeType =
  | 'standard'
  | 'eating'
  | 'math'
  | 'large-numbers'
  | 'positional-notation'
  | 'alphabet'
  | 'spelling'
  | 'watertoiletcheck'

type PresetChoreModeDefinition = {
  hidePrimaryButtonInChore: boolean
}

const presetChoreModeDefinitions: Record<
  Exclude<ChoreModeType, 'standard'>,
  PresetChoreModeDefinition
> = {
  eating: {
    hidePrimaryButtonInChore: false,
  },
  math: {
    hidePrimaryButtonInChore: false,
  },
  'large-numbers': {
    hidePrimaryButtonInChore: false,
  },
  'positional-notation': {
    hidePrimaryButtonInChore: false,
  },
  alphabet: {
    hidePrimaryButtonInChore: true,
  },
  spelling: {
    hidePrimaryButtonInChore: true,
  },
  watertoiletcheck: {
    hidePrimaryButtonInChore: false,
  },
}

export const isInChoreStage = (stage: ChoreStage) => stage !== 'setup'

export const isFinalChoreStage = (stage: ChoreStage) => stage === 'completed'

export const shouldHidePresetChoreTitle = (stage: ChoreStage) =>
  isInChoreStage(stage)

export const shouldHidePresetChoreStars = (stage: ChoreStage) =>
  isInChoreStage(stage)

export const shouldUseResetUtility = (stage: ChoreStage) =>
  isInChoreStage(stage)

export const shouldHidePresetPrimaryButton = (
  type: Exclude<ChoreModeType, 'standard'>,
  stage: ChoreStage
) =>
  isFinalChoreStage(stage) ||
  (stage === 'activity' &&
    presetChoreModeDefinitions[type].hidePrimaryButtonInChore)

export const getTestPrimaryActionLabel = (stage: ChoreStage) => {
  if (stage === 'activity') return 'Check Answer'
  return 'Start'
}

export const getDinnerPrimaryActionLabel = (
  stage: ChoreStage,
  isTimerRunning: boolean
) => {
  if (stage === 'activity' && isTimerRunning) return 'Bite'
  return 'Start'
}

export const getActivityPrimaryActionLabel = (stage: ChoreStage) => {
  if (stage === 'activity') return 'Finish'
  return 'Start'
}

