type ThemeOption = {
  id: ThemeId
  label: string
  image: string
}

type ChildDefinitionDescriptorDeps = {
  theme: Theme
  activeChildId: string | null
  themeOptions: ThemeOption[]
  carouselItems: Array<{ id: ThemeId; label: string; icon: ReactNode }>
  nameDrafts: Record<string, string>
  setNameDraft: (childId: string, value: string) => void
  commitDisplayName: (childId: string, value: string) => void | Promise<void>
  updateChildField: (
    childId: string,
    value: Record<string, unknown>
  ) => void | Promise<void>
  changeTheme: (child: ChildProfile, themeId: ThemeId) => void | Promise<void>
  selectChild: (childId: string) => void | Promise<void>
}

type TestFailureModeChoice = 'failure' | 'success'

const TEST_FAILURE_MODE_OPTIONS: SegmentedChoiceOption<TestFailureModeChoice>[] =
  [
    {
      value: 'failure',
      label: 'Tests have failure mode',
      icon: quizIncorrectIcon,
    },
    {
      value: 'success',
      label: 'Tests do not have failure mode',
      icon: quizCorrectIcon,
    },
  ]

type RewardDefinitionDescriptorDeps = {
  theme: Theme
  activeChildId: string | null
  activeChildStars: number
  isRedeeming: boolean
  handleGiveReward: (reward: RewardRecord) => void | Promise<void>
}

const renderRewardAvailableSummary = (reward: RewardRecord, theme: Theme) => {
  const image = getRewardImage(reward.imageKey)

  const rewardCostFrameStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    position: 'relative',
    width: '100%',
    minHeight: '116px',
    padding: '10px',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    border: `3px dashed ${theme.colors.primary}55`,
    background: `${theme.colors.bg}88`,
    overflow: 'visible',
    boxSizing: 'border-box',
  }

  const imageLaneStyle: CSSProperties = {
    flex: '0 0 38%',
    minWidth: '96px',
    maxWidth: '152px',
    marginRight: '-26px',
    position: 'relative',
    zIndex: 2,
  }

  const imageFrameStyle: CSSProperties = {
    width: '100%',
    aspectRatio: '1',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'visible',
  }

  const starLaneStyle: CSSProperties = {
    flex: '1 1 66%',
    minWidth: 0,
    position: 'relative',
    zIndex: 1,
  }

  return (
    <div
      aria-label={`${reward.title} available reward`}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: `${uiTokens.singleVerticalSpace}px`,
        minWidth: 0,
        flex: 1,
      }}
    >
      <div
        style={{
          ...getStandardActionHeadingStyle(theme),
        }}
      >
        {reward.title}
      </div>

      <div style={rewardCostFrameStyle}>
        {image && (
          <div style={imageLaneStyle}>
            <div style={imageFrameStyle}>
              <img
                src={image}
                alt={`${reward.title} reward`}
                style={{
                  width: '112%',
                  height: '112%',
                  objectFit: 'contain',
                  display: 'block',
                }}
              />
            </div>
          </div>
        )}

        <div style={starLaneStyle}>
          <StarDisplay
            count={reward.costStars}
            animate={false}
            style={{
              width: '100%',
              minHeight: '84px',
              padding: image ? '10px 10px 10px 4px' : '10px',
              background: 'transparent',
              border: '0',
              boxSizing: 'border-box',
            }}
          />
        </div>
      </div>
    </div>
  )
}

export const createChildDefinitionListRowDescriptor = (
  deps: ChildDefinitionDescriptorDeps
): ListRowDescriptor<ChildProfile> => ({
  renderItem: (child) => {
    const currentThemeId = child.themeId || 'princess'
    const currentThemeIndex = Math.max(
      0,
      deps.themeOptions.findIndex((option) => option.id === currentThemeId)
    )

    return (
      <div
        className="flex flex-col"
        style={{ gap: `${uiTokens.singleVerticalSpace}px` }}
      >
        <ActionTextInput
          theme={deps.theme}
          label="Name"
          value={deps.nameDrafts[child.id] ?? child.displayName}
          onChange={(value) => deps.setNameDraft(child.id, value)}
          onCommit={(value) => deps.commitDisplayName(child.id, value)}
          maxLength={40}
          baseColor={deps.theme.colors.primary}
          inputAriaLabel="Child name"
          transparent
        />

        <Carousel
          key={`${child.id}-${currentThemeId}`}
          items={deps.carouselItems}
          title="Select Theme"
          initialIndex={currentThemeIndex}
          onChange={(index) => {
            const selected = deps.themeOptions[index]
            if (!selected) return
            deps.changeTheme(child, selected.id)
          }}
        />

        <StarDisplay
          theme={deps.theme}
          count={child.totalStars}
          editable
          min={0}
          max={999}
          onChange={(value) =>
            deps.updateChildField(child.id, { totalStars: value })
          }
        />

        <SegmentedChoiceControl
          theme={deps.theme}
          value={child.testFailureModeEnabled ? 'failure' : 'success'}
          options={TEST_FAILURE_MODE_OPTIONS}
          onChange={(value) =>
            deps.updateChildField(child.id, {
              testFailureModeEnabled: value === 'failure',
            })
          }
          ariaLabel="Test failure mode"
        />
      </div>
    )
  },
  isHighlighted: (child) => deps.activeChildId === child.id,
  getPrimaryAction: (child) => ({
    label: deps.activeChildId === child.id ? 'Active' : 'Select',
    ariaLabel:
      deps.activeChildId === child.id ? 'Active child' : 'Select child',
    icon:
      deps.theme.id === 'princess' ? (
        <img
          src={
            deps.activeChildId === child.id
              ? princessActiveIcon
              : princessSelectIcon
          }
          alt={deps.activeChildId === child.id ? 'Active' : 'Select'}
          className="h-6 w-6 object-contain"
        />
      ) : deps.activeChildId === child.id ? (
        '✅'
      ) : (
        '⭐'
      ),
    showLabel: false,
    disabled: deps.activeChildId === child.id,
    variant: deps.theme.id === 'princess' ? 'neutral' : 'primary',
    onClick: (item) => deps.selectChild(item.id),
  }),
})

export const createRewardDefinitionListRowDescriptor = (
  deps: RewardDefinitionDescriptorDeps
): ListRowDescriptor<RewardRecord> => ({
  renderItem: (reward) => renderRewardAvailableSummary(reward, deps.theme),
  getPrimaryAction: (reward) => {
    const hasEnoughStars = deps.activeChildStars >= reward.costStars

    return {
      label: hasEnoughStars ? 'Buy Reward' : 'Need Stars',
      icon: hasEnoughStars ? (
        <img
          src={princessBuyRewardIcon}
          alt="Buy Reward"
          className="h-6 w-6 object-contain"
        />
      ) : (
        '🔒'
      ),
      disabled: deps.isRedeeming || !deps.activeChildId || !hasEnoughStars,
      variant: 'primary',
      showLabel: false,
      onClick: (item) => deps.handleGiveReward(item),
    }
  },
})

import type { ReactNode } from 'react'
import { princessResetIcon } from '../assets/themes/princess/assets'
import type { Theme } from '../contexts/ThemeContext'
import type {
  ResolvedListAction,
  ResolvedListUtilityAction,
} from './listDescriptorTypes'
import {
  getActivityPrimaryActionLabel,
  getDinnerPrimaryActionLabel,
  getTestPrimaryActionLabel,
  isFinalChoreStage,
  shouldHidePresetPrimaryButton,
  shouldUseResetUtility,
  type ChoreModeType,
  type ChoreStage,
} from './choreModeDefinitions'

type PresetChoreType = Exclude<ChoreModeType, 'standard'>

type SharedPrimaryActionBase = {
  stage: ChoreStage
  icon: ReactNode
  disabled?: boolean
}

type DinnerPrimaryActionConfig<T> = SharedPrimaryActionBase & {
  isTimerRunning: boolean
  onStart: (item: T) => void | Promise<void>
  onBite: (item: T) => void | Promise<void>
  onReset: (item: T) => void | Promise<void>
}

type TestPrimaryActionConfig<T> = SharedPrimaryActionBase & {
  choreType: Exclude<PresetChoreType, 'eating'>
  onStart: (item: T) => void | Promise<void>
  onCheck: (item: T) => void | Promise<void>
  onReset: (item: T) => void | Promise<void>
}

type ActivityPrimaryActionConfig<T> = SharedPrimaryActionBase & {
  choreType: Exclude<
    PresetChoreType,
    | 'eating'
    | 'math'
    | 'large-numbers'
    | 'positional-notation'
    | 'alphabet'
    | 'spelling'
  >
  onStart: (item: T) => void | Promise<void>
  onFinish: (item: T) => void | Promise<void>
  onReset: (item: T) => void | Promise<void>
}

type PresetUtilityActionConfig<T> = {
  stage: ChoreStage
  resetAriaLabel: string
  deleteAriaLabel: string
  onReset: (item: T) => void | Promise<void>
  onDelete: (item: T) => void | Promise<void>
  theme: Theme
}

export const createDeleteUtilityAction = <T,>(
  ariaLabel: string,
  onClick: (item: T) => void | Promise<void>
): ResolvedListUtilityAction<T> => ({
  label: 'Delete',
  ariaLabel,
  exits: true,
  variant: 'danger',
  onClick,
})

export const createResetUtilityAction = <T,>(
  ariaLabel: string,
  onClick: (item: T) => void | Promise<void>,
  theme: Theme
): ResolvedListUtilityAction<T> => ({
  label: 'Reset',
  ariaLabel,
  icon:
    theme.id === 'princess' ? (
      <img
        src={princessResetIcon}
        alt="Reset"
        className="h-6 w-6 object-contain"
      />
    ) : undefined,
  exits: false,
  variant: 'neutral',
  onClick,
})

export const createPresetUtilityAction = <T,>({
  stage,
  resetAriaLabel,
  deleteAriaLabel,
  onReset,
  onDelete,
  theme,
}: PresetUtilityActionConfig<T>): ResolvedListUtilityAction<T> =>
  shouldUseResetUtility(stage)
    ? createResetUtilityAction(resetAriaLabel, onReset, theme)
    : createDeleteUtilityAction(deleteAriaLabel, onDelete)

export const createPresetDinnerPrimaryAction = <T,>({
  stage,
  isTimerRunning,
  icon,
  disabled,
  onStart,
  onBite,
  onReset,
}: DinnerPrimaryActionConfig<T>): ResolvedListAction<T> => ({
  label: getDinnerPrimaryActionLabel(stage, isTimerRunning),
  icon,
  disabled,
  hideButton: isFinalChoreStage(stage),
  variant: 'primary',
  showLabel: false,
  onClick: (item) => {
    if (isFinalChoreStage(stage)) {
      return onReset(item)
    }

    if (stage === 'activity' && isTimerRunning) {
      return onBite(item)
    }

    return onStart(item)
  },
})

export const createPresetTestPrimaryAction = <T,>({
  choreType,
  stage,
  icon,
  disabled,
  onStart,
  onCheck,
  onReset,
}: TestPrimaryActionConfig<T>): ResolvedListAction<T> => ({
  label: getTestPrimaryActionLabel(stage),
  icon,
  disabled,
  hideButton: shouldHidePresetPrimaryButton(choreType, stage),
  variant: 'primary',
  showLabel: false,
  onClick: (item) => {
    if (isFinalChoreStage(stage)) {
      return onReset(item)
    }

    if (stage === 'activity') {
      return onCheck(item)
    }

    return onStart(item)
  },
})

export const createPresetActivityPrimaryAction = <T,>({
  choreType,
  stage,
  icon,
  disabled,
  onStart,
  onFinish,
  onReset,
}: ActivityPrimaryActionConfig<T>): ResolvedListAction<T> => ({
  label: getActivityPrimaryActionLabel(stage),
  icon,
  disabled,
  hideButton: shouldHidePresetPrimaryButton(choreType, stage),
  variant: 'primary',
  showLabel: false,
  onClick: (item) => {
    if (isFinalChoreStage(stage)) {
      return onReset(item)
    }

    if (stage === 'activity') {
      return onFinish(item)
    }

    return onStart(item)
  },
})

