              <span
                aria-hidden="true"
                style={{
                  width: '44px',
                  height: '44px',
                  borderRadius: 14,
                  border: `3px dashed ${deps.theme.colors.primary}`,
                  display: 'block',
                  opacity: 0.55,
                }}
              />
            ),
          }))}
          title="Chore image"
          initialIndex={Math.max(
            0,
            choreImageOptions.findIndex((option) => option.id === item.imageKey)
