import {
  getManageDinnerBitesLeft,
  getManageDinnerRemaining,
  getManageTaskCompletedAt,
  getManageToiletStatus,
  getManageWaterLevel,
  isEatingTask,
  isEatingTodo,
  isWaterToiletTask,
  isWaterToiletTodo,
  type TaskRecord,
  type TaskType,
  type TaskWithEphemeral,
  type TodoRecord,
} from '../data/types'
import {
  calculateWaterToiletStars,
  getNextToiletStatus,
  getNextWaterLevel,
} from '../lib/choreLogic'
import type { ChoreStage } from './choreModeDefinitions'
import type {
  PrincessAsset,
  UnifiedChoreDeps,
  UnifiedChoreItem,
} from './unifiedChoreDescriptorTypes'
import {
  princessQuizCorrectImage,
  princessQuizIncorrectImage,
} from '../assets/themes/princess/assets'

export const isTaskItem = (item: UnifiedChoreItem): item is TaskWithEphemeral =>
  'taskType' in item

export const getChoreType = (item: UnifiedChoreItem): TaskType =>
  isTaskItem(item) ? item.taskType : item.sourceTaskType

export const isTestType = (type: TaskType) =>
  type === 'math' ||
  type === 'large-numbers' ||
  type === 'positional-notation' ||
  type === 'alphabet' ||
  type === 'spelling'

export const createUnifiedChoreState = (deps: UnifiedChoreDeps) => {
  const princessAsset = (asset?: string): PrincessAsset =>
    deps.theme.id === 'princess' ? asset : undefined
  const testOutcomeImages = () => ({
    completionImage: princessAsset(princessQuizCorrectImage),
    failureImage: princessAsset(princessQuizIncorrectImage),
  })

  const hasActiveDinnerCooldown = (item: UnifiedChoreItem) =>
    deps.activeDinnerId === item.id &&
    typeof deps.biteCooldownEndsAt === 'number' &&
    deps.biteCooldownEndsAt > Date.now()

  const isCompleted = (item: UnifiedChoreItem) =>
    isTaskItem(item)
      ? Boolean(getManageTaskCompletedAt(item))
      : Boolean(item.completedAt)

  const isDinnerAwaitingFinalCooldown = (item: UnifiedChoreItem) => {
    if (getChoreType(item) !== 'eating' || !isCompleted(item)) return false

    if (isTaskItem(item)) {
      return isEatingTask(item) && getManageDinnerBitesLeft(item) <= 0
        ? hasActiveDinnerCooldown(item)
        : false
    }

    return isEatingTodo(item) && item.dinnerBitesLeft <= 0
      ? hasActiveDinnerCooldown(item)
      : false
  }

  const isDinnerTimedOut = (item: UnifiedChoreItem) => {
    if (getChoreType(item) !== 'eating') return false

    if (isTaskItem(item)) {
      if (!isEatingTask(item)) return false
      return hasExpiredDinnerTimer(
        getManageDinnerRemaining(item),
        item.manageDinnerTimerStartedAt,
        getManageDinnerBitesLeft(item)
      )
    }

    return isEatingTodo(item)
      ? hasExpiredDinnerTimer(
          item.dinnerRemainingSeconds,
          item.dinnerTimerStartedAt,
          item.dinnerBitesLeft
        )
      : false
  }

  const getStage = (item: UnifiedChoreItem): ChoreStage => {
    if (isCompleted(item) || isDinnerTimedOut(item)) {
      return isDinnerAwaitingFinalCooldown(item) ? 'activity' : 'completed'
    }

    return isActiveItem(deps, item.id) ? 'activity' : 'setup'
  }

  const getWaterToiletDelta = (item: UnifiedChoreItem) => {
    if (isTaskItem(item)) {
      if (!isWaterToiletTask(item)) return item.starValue
      return calculateWaterToiletStars(
        getManageWaterLevel(item),
        getManageToiletStatus(item)
      )
    }

    if (!isWaterToiletTodo(item)) return item.starValue
    return calculateWaterToiletStars(item.waterLevel, item.toiletStatus)
  }

  const getWaterToiletRenderState = (item: UnifiedChoreItem) => {
    if (isTaskItem(item)) return getTaskWaterToiletRenderState(deps, item)
    return getTodoWaterToiletRenderState(deps, item)
  }

  return {
    princessAsset,
    testOutcomeImages,
    isCompleted,
    getStage,
    getWaterToiletDelta,
    getWaterToiletRenderState,
  }
}

const hasExpiredDinnerTimer = (
  remaining: number,
  startedAt: number | null | undefined,
  bitesLeft: number
) => {
  if (!startedAt) return remaining <= 0 && bitesLeft > 0
  const elapsed = (Date.now() - startedAt) / 1000
  return remaining - elapsed <= 0 && bitesLeft > 0
}

const isActiveItem = (deps: UnifiedChoreDeps, id: string) =>
  deps.activeMathId === id ||
  deps.activeLargeNumbersId === id ||
  deps.activePVId === id ||
  deps.activeAlphabetId === id ||
  deps.activeSpellingId === id ||
  deps.activeDinnerId === id ||
  deps.activeWaterToiletId === id

const getTaskWaterToiletRenderState = (
  deps: UnifiedChoreDeps,
  item: TaskWithEphemeral
) => {
  if (!isWaterToiletTask(item)) return null

  const waterLevel = getManageWaterLevel(item)
  const toiletStatus = getManageToiletStatus(item)

  return {
    isCompleted: Boolean(item.manageWaterToiletCompletedAt),
    waterLevel,
    toiletStatus,
    starDelta: calculateWaterToiletStars(waterLevel, toiletStatus),
    onCycleWater: () =>
      deps.onUpdateEphemeral?.(item.id, {
        manageWaterLevel: getNextWaterLevel(waterLevel),
      }),
    onCycleToilet: () =>
      deps.onUpdateEphemeral?.(item.id, {
        manageToiletStatus: getNextToiletStatus(toiletStatus),
      }),
  }
}

const getTodoWaterToiletRenderState = (
  deps: UnifiedChoreDeps,
  item: TodoRecord
) => {
  if (!isWaterToiletTodo(item)) return null

  return {
    isCompleted: Boolean(item.completedAt),
    waterLevel: item.waterLevel,
    toiletStatus: item.toiletStatus,
    starDelta: calculateWaterToiletStars(item.waterLevel, item.toiletStatus),
    onCycleWater: () =>
      deps.onUpdateTodoField?.(item.id, {
        waterLevel: getNextWaterLevel(item.waterLevel),
      }),
    onCycleToilet: () =>
      deps.onUpdateTodoField?.(item.id, {
        toiletStatus: getNextToiletStatus(item.toiletStatus),
      }),
  }
}

export type UnifiedChoreState = ReturnType<typeof createUnifiedChoreState>
export type RenderableTaskRecord = TaskRecord

import {
  princessEatingFailImage,
  princessEatingFullImage,
  princessPlateImage,
} from '../assets/themes/princess/assets'
import {
  DEFAULT_DINNER_BITES,
  DEFAULT_DINNER_DURATION_SECONDS,
  getManageDinnerBitesLeft,
  getManageDinnerRemaining,
  isEatingTask,
  isEatingTodo,
  type EatingTaskWithEphemeral,
  type EatingTodo,
} from '../data/types'
import type { ChoreStage } from './choreModeDefinitions'
import { renderDinnerChore } from './presetChoreRenderers'
import type {
  UnifiedChoreDeps,
  UnifiedChoreItem,
} from './unifiedChoreDescriptorTypes'
import { isTaskItem, type UnifiedChoreState } from './unifiedChoreState'
import { clamp, noop } from './unifiedChoreRenderUtils'

export const renderEatingContent = (
  deps: UnifiedChoreDeps,
  state: UnifiedChoreState,
  item: UnifiedChoreItem,
  stage: ChoreStage
) => {
  const isActive = deps.activeDinnerId === item.id
  if (isTaskItem(item)) {
    return isEatingTask(item)
      ? renderEatingTask(deps, state, item, isActive, stage)
      : null
  }

  return isEatingTodo(item)
    ? renderEatingTodo(deps, state, item, isActive)
    : null
}

const renderEatingTask = (
  deps: UnifiedChoreDeps,
  state: UnifiedChoreState,
  item: EatingTaskWithEphemeral,
  isActive: boolean,
  stage: ChoreStage
) => {
  const isCompleted = Boolean(item.manageDinnerCompletedAt)
  const isManage = deps.mode === 'manage'
  if (!isActive && !isCompleted && (!isManage || stage !== 'setup')) {
    return null
  }

  return renderDinnerChore({
    theme: deps.theme,
    duration: item.dinnerDurationSeconds ?? DEFAULT_DINNER_DURATION_SECONDS,
    remaining: getManageDinnerRemaining(item),
    totalBites: item.dinnerTotalBites ?? DEFAULT_DINNER_BITES,
    bitesLeft: getManageDinnerBitesLeft(item),
    starReward: item.starValue,
    isTimerRunning: isActive,
    timerStartedAt: item.manageDinnerTimerStartedAt,
    plateImage: state.princessAsset(princessPlateImage),
    onAdjustTime: (delta) => {
      const next = clamp(
        (item.dinnerDurationSeconds ?? DEFAULT_DINNER_DURATION_SECONDS) + delta,
        5 * 60,
        30 * 60
      )
      deps.onUpdateTaskField?.(item.id, { dinnerDurationSeconds: next })
      deps.onUpdateEphemeral?.(item.id, {
        manageDinnerRemainingSeconds: next,
      })
    },
    onAdjustBites: (delta) => {
      const next = clamp(
        (item.dinnerTotalBites ?? DEFAULT_DINNER_BITES) + delta,
        1,
        16
      )
      deps.onUpdateTaskField?.(item.id, { dinnerTotalBites: next })
      deps.onUpdateEphemeral?.(item.id, { manageDinnerBitesLeft: next })
    },
    onStarsChange: (value) =>
      deps.onUpdateTaskField?.(item.id, { starValue: value }),
    onExpire: () => deps.onExpireDinner?.(item),
    isCompleted,
    ...state.testOutcomeImages(),
    biteCooldownSeconds: deps.biteCooldownSeconds,
    biteCooldownEndsAt: deps.biteCooldownEndsAt,
    biteIcon: state.princessAsset(deps.activePrincessMealIcon),
    showSetupControls: isManage && !isActive && !isCompleted,
    showStarReward: isManage && !isActive && !isCompleted,
  })
}

const renderEatingTodo = (
  deps: UnifiedChoreDeps,
  state: UnifiedChoreState,
  item: EatingTodo,
  isActive: boolean
) => {
  const isCompleted = Boolean(item.completedAt)
  if (!isActive && !isCompleted) return null

  return renderDinnerChore({
    theme: deps.theme,
    duration: item.dinnerDurationSeconds ?? DEFAULT_DINNER_DURATION_SECONDS,
    remaining: item.dinnerRemainingSeconds,
    totalBites: item.dinnerTotalBites ?? DEFAULT_DINNER_BITES,
    bitesLeft: item.dinnerBitesLeft,
    starReward: item.starValue,
    isTimerRunning: isActive,
    timerStartedAt: item.dinnerTimerStartedAt,
    plateImage: state.princessAsset(princessPlateImage),
    isCompleted,
    completionImage: state.princessAsset(princessEatingFullImage),
    failureImage: state.princessAsset(princessEatingFailImage),
    biteCooldownSeconds: deps.biteCooldownSeconds,
    biteCooldownEndsAt: deps.biteCooldownEndsAt,
    biteIcon: state.princessAsset(deps.activePrincessMealIcon),
    onAdjustTime: noop,
    onAdjustBites: noop,
    onStarsChange: noop,
    onExpire: () => deps.onExpireDinner?.(item),
    showSetupControls: false,
    showStarReward: false,
  })
}

import ChoreOutcomeView from '../components/ChoreOutcomeView'
import { getWaterToiletOutcome } from '../lib/choreLogic'
import type { ChoreStage } from './choreModeDefinitions'
import { renderWaterToiletChore } from './presetChoreRenderers'
import type {
  UnifiedChoreDeps,
  UnifiedChoreItem,
} from './unifiedChoreDescriptorTypes'
import type { UnifiedChoreState } from './unifiedChoreState'
import { getWaterToiletOutcomeImage } from './waterToiletAssets'

export const renderWaterToiletContent = (
  deps: UnifiedChoreDeps,
  state: UnifiedChoreState,
  item: UnifiedChoreItem,
  stage: ChoreStage
) => {
  const renderState = state.getWaterToiletRenderState(item)
  if (!renderState) return null

  if (stage === 'completed') {
    const outcome = getWaterToiletOutcome(
      renderState.waterLevel,
      renderState.toiletStatus
    )
    return (
      <ChoreOutcomeView
        imageSrc={getWaterToiletOutcomeImage(deps.theme, outcome)}
        outcome={outcome}
      />
    )
  }

  if (deps.activeWaterToiletId !== item.id) return null

  return renderWaterToiletChore({
    theme: deps.theme,
    waterLevel: renderState.waterLevel,
    toiletStatus: renderState.toiletStatus,
    starDelta: renderState.starDelta,
    isInteractive: true,
    isCompleted: false,
    onCycleWater: renderState.onCycleWater,
    onCycleToilet: renderState.onCycleToilet,
  })
}

import {
  princessDidPeePeeImage,
  princessFlaskOneThirdImage,
  princessFlaskTwoThirdsImage,
  princessFlaskFullImage,
  princessDrinkSuccessImage,
  princessNotPeePeeImage,
} from '../assets/themes/princess/assets'
import type { Theme } from '../contexts/ThemeContext'
import type { ToiletStatus, WaterLevel } from '../data/types'
import type { WaterToiletOutcome } from '../lib/choreLogic'

export const waterLabels: Record<WaterLevel, string> = {
  full: 'Full flask',
  twothirds: 'Two-thirds full flask',
  onethird: 'One-third full flask',
  empty: 'Empty flask',
}

export const toiletLabels: Record<ToiletStatus, string> = {
  notpeepee: 'Has not gone to the toilet',
  didpeepee: 'Has gone to the toilet',
}

export const fallbackWaterVisuals: Record<WaterLevel, string> = {
  full: '💧💧💧',
  twothirds: '💧💧',
  onethird: '💧',
  empty: '🫙',
}

export const fallbackToiletVisuals: Record<ToiletStatus, string> = {
  notpeepee: '🚫',
  didpeepee: '✅',
}

export const getWaterImage = (theme: Theme, waterLevel: WaterLevel) => {
  if (theme.id !== 'princess') return null

  switch (waterLevel) {
    case 'full':
      return princessFlaskFullImage
    case 'twothirds':
      return princessFlaskTwoThirdsImage
    case 'onethird':
      return princessFlaskOneThirdImage
    case 'empty':
      return princessDrinkSuccessImage
  }
}

export const getToiletImage = (theme: Theme, toiletStatus: ToiletStatus) => {
  if (theme.id !== 'princess') return null
  return toiletStatus === 'didpeepee'
    ? princessDidPeePeeImage
    : princessNotPeePeeImage
}

export const getWaterToiletOutcomeImage = (
  theme: Theme,
  outcome: WaterToiletOutcome
) => {
  if (theme.id !== 'princess') return undefined
  return outcome === 'success'
    ? princessDrinkSuccessImage
    : princessNotPeePeeImage
}

