                  Ones
                </span>

                <div
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 2,
                    marginBottom: 8,
                    width: '100%',
                    paddingLeft: 4,
                    paddingRight: 4,
                    boxSizing: 'border-box',
                  }}
                >
                  <StepperButton
                    theme={theme}
                    direction="prev"
                    onClick={() =>
                      setUserOnes((value) => Math.max(0, value - 1))
