import { useEffect, useMemo, useState } from 'react'
import type { CSSProperties, ReactNode } from 'react'
import { useTheme } from '../../contexts/ThemeContext'

type CarouselItem = {
  id: string | number
  label: string
  icon: ReactNode
}

type CarouselProps = {
  items: CarouselItem[]
  title?: string
  initialIndex?: number
  onChange?: (index: number) => void
  className?: string
  style?: CSSProperties
}

const ITEM_SIZE = 90
const GAP = 16
const ACTIVE_SCALE = 1.3
const SIDE_SCALE = 1

const getWrappedIndex = (index: number, length: number) =>
  (index + length) % length

const Carousel = ({
  items,
  initialIndex = 0,
  onChange,
  className,
  style,
}: CarouselProps) => {
  const { theme } = useTheme()
  const safeItems = useMemo(() => items ?? [], [items])
  const [currentIndex, setCurrentIndex] = useState(
    Math.max(0, Math.min(initialIndex, safeItems.length - 1))
  )

  useEffect(() => {
    if (safeItems.length === 0) return
    setCurrentIndex((prev) => Math.max(0, Math.min(prev, safeItems.length - 1)))
  }, [safeItems.length])

  useEffect(() => {
    if (!onChange) return
    onChange(currentIndex)
  }, [currentIndex, onChange])

  const visibleItems = useMemo(() => {
    if (safeItems.length === 0) return []
    return [
      safeItems[getWrappedIndex(currentIndex - 1, safeItems.length)],
      safeItems[currentIndex],
      safeItems[getWrappedIndex(currentIndex + 1, safeItems.length)],
    ]
  }, [safeItems, currentIndex])

  const navigate = (delta: number) => {
    if (safeItems.length <= 1) return
    setCurrentIndex((index) => getWrappedIndex(index + delta, safeItems.length))
  }

  if (safeItems.length === 0) return null

  const rootStyle: CSSProperties = {
    background: `linear-gradient(180deg, ${theme.colors.surface} 0%, ${theme.colors.bg} 100%)`,
    border: `6px solid ${theme.colors.primary}`,
    padding: '14px 0 18px',
    textAlign: 'center',
    boxShadow:
      theme.id === 'space'
        ? `0 0 16px ${theme.colors.primary}55`
        : `0 6px 0 ${theme.colors.accent}80`,
    borderRadius: 16,
  }

  const stageStyle: CSSProperties = {
    position: 'relative',
    width: '100%',
    height: '170px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  }

  const trackStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    gap: `${GAP}px`,
    willChange: 'transform',
