import type { CSSProperties } from 'react'
import type { Theme } from '../../contexts/ThemeContext'
import { uiTokens } from '../../tokens'
import {
  getStandardPrimaryActionStyle,
  getStandardUtilityActionStyle,
  type StandardActionVariant,
