type IconFit = 'contain' | 'cover'

type StandardIconImageProps = {
  src: string
  fit?: IconFit
  width?: number | string
  height?: number | string
  opacity?: number
  className?: string
  style?: CSSProperties
}

export const StandardIconImage = ({
  src,
  fit = 'contain',
  width = 40,
  height = 40,
  opacity,
  className,
  style,
}: StandardIconImageProps) => (
  <img
    src={src}
    alt=""
    aria-hidden="true"
    className={className}
    style={{
      width,
      height,
      maxWidth: width,
      maxHeight: height,
      objectFit: fit,
      objectPosition: 'center',
      display: 'block',
      flex: '0 0 auto',
      opacity,
      ...style,
    }}
  />
)

type IconActionButtonProps = {
  theme: Theme
  icon: string
  ariaLabel: string
  onClick: () => void | Promise<void>
  disabled?: boolean
  variant?: StandardActionVariant
  shape?: 'primary' | 'utility'
  fit?: IconFit
  iconWidth?: number | string
  iconHeight?: number | string
  iconOpacity?: number
  className?: string
  style?: CSSProperties
}

export const IconActionButton = ({
  theme,
  icon,
  ariaLabel,
  onClick,
  disabled,
  variant,
  shape = 'utility',
  fit = shape === 'primary' ? 'cover' : 'contain',
  iconWidth = shape === 'primary' ? '100%' : 40,
  iconHeight = shape === 'primary' ? '100%' : 40,
  iconOpacity,
  className,
  style,
}: IconActionButtonProps) => (
  <button
    type="button"
    className={`whimsical-btn ${shape === 'utility' ? 'whimsical-btn-utility' : ''} ${className ?? ''}`.trim()}
    onClick={onClick}
    disabled={disabled}
    aria-label={ariaLabel}
    style={{
      ...(shape === 'primary'
        ? getStandardPrimaryActionStyle(theme, variant ?? 'primary')
        : getStandardUtilityActionStyle(theme, variant ?? 'neutral')),
