    }
    .whimsical-card:nth-child(3n) {
      animation-delay: 0.6s;
    }
    .whimsical-card-exiting {
      animation: whimsical-poof 0.4s ease-in forwards !important;
      pointer-events: none;
    }
    .whimsical-btn {
      transition: transform 0.15s ease, box-shadow 0.15s ease;
      cursor: pointer;
    }
    .whimsical-btn:hover:not(:disabled) {
      transform: translateY(-3px) scale(1.02);
    }
    .whimsical-btn:active:not(:disabled) {
      transform: scale(0.92) translateY(4px) !important;
    }
    .whimsical-btn-utility:hover:not(:disabled) {
      transform: translateY(-2px);
      border-color: #cbd5e1;
      color: #64748b;
    }
    .whimsical-btn-delete:hover:not(:disabled) {
      background: #fef2f2 !important;
      color: #ef4444 !important;
      border-color: #fecaca !important;
    }
  `
  document.head.appendChild(style)
}

export type ActionConfig<T> = {
  label: string | ((item: T) => string)
  onClick: (item: T) => void | Promise<void>
  icon?: ReactNode | ((item: T) => ReactNode)
  ariaLabel?: string | ((item: T) => string)
  disabled?: (item: T) => boolean
  hideButton?: boolean | ((item: T) => boolean)
  variant?:
    | 'primary'
    | 'neutral'
    | 'danger'
    | ((item: T) => 'primary' | 'neutral' | 'danger')
  showLabel?: boolean | ((item: T) => boolean)
}

export type UtilityActionConfig<T> = ActionConfig<T> & {
  exits?: boolean | ((item: T) => boolean)
}

export type StandardActionListProps<T> = {
  theme: Theme
  items: T[]
  renderItem: (item: T) => ReactNode
  primaryAction: ActionConfig<T>
  onEdit?: (item: T) => void | Promise<void>
  onDelete: (item: T) => void | Promise<void>
  utilityAction?: UtilityActionConfig<T>
  addLabel: string
  onAdd: () => void | Promise<void>
  addDisabled?: boolean
  isLoading?: boolean
  emptyState?: ReactNode
  getKey?: (item: T) => string
  isHighlighted?: (item: T) => boolean
  /** Optional: Return star count for an item to render the star field */
  getStarCount?: (item: T) => number | undefined
  /** When true, the Edit button is hidden. Can be scoped per row. */
  hideEdit?: boolean | ((item: T) => boolean)
  /** Key of the item currently being edited inline */
  editingId?: string
  /** Renders the full inline edit UI in place of normal row content when editingId matches */
  renderInlineEdit?: (item: T) => ReactNode
  /** When provided, renders an inline "new item" editor card at the bottom of the list
   *  (the Add button card is suppressed while this is set) */
  inlineNewRow?: ReactNode
  /** When false, renders inlineNewRow directly instead of wrapping it in an add-card frame. */
  frameInlineNewRow?: boolean
  /** When true, suppresses the add button card entirely */
  hideAdd?: boolean
}

const resolveValue = <T,>(
  value: string | ReactNode | ((item: T) => string | ReactNode),
  item: T
) => (typeof value === 'function' ? value(item) : value)

const resolveTextValue = <T,>(
  value: string | ((item: T) => string),
  item: T
) => (typeof value === 'function' ? value(item) : value)

const runActionSafely = (
  actionName: string,
  action: () => void | Promise<void>
) => {
  try {
    const result = action()
    if (result instanceof Promise) {
      result.catch((error) => {
        console.error(`Failed to run ${actionName}`, error)
      })
    }
  } catch (error) {
    console.error(`Failed to run ${actionName}`, error)
  }
}

// Wrapper for individual action card with exit animation support
const ActionCard = <T,>({
  item,
  index,
  theme,
  isDarkTheme,
  rowBaseStyle,
  isItemHighlighted,
  renderItem,
  primaryAction,
  primaryDisabled,
  onEdit,
  onDelete,
  utilityAction,
  getActionStyle,
  actionBaseStyle,
  getKey,
  getStarCount,
  hideEdit,
  editingId,
  renderInlineEdit,
}: {
  item: T
  index: number
  theme: Theme
  isDarkTheme: boolean
  rowBaseStyle: CSSProperties
  isItemHighlighted: boolean
  renderItem: (item: T) => ReactNode
  primaryAction: ActionConfig<T>
  primaryDisabled: boolean
  onEdit?: (item: T) => void | Promise<void>
  onDelete: (item: T) => void | Promise<void>
  utilityAction?: UtilityActionConfig<T>
  getActionStyle: (variant?: ActionConfig<T>['variant']) => CSSProperties
  actionBaseStyle: CSSProperties
  getKey?: (item: T) => string
  getStarCount?: (item: T) => number | undefined
  hideEdit?: boolean | ((item: T) => boolean)
  editingId?: string
  renderInlineEdit?: (item: T) => ReactNode
}) => {
  const [isExiting, setIsExiting] = useState(false)
  const cardRef = useRef<HTMLDivElement>(null)
  const hideUtilityButton =
    typeof utilityAction?.hideButton === 'function'
      ? utilityAction.hideButton(item)
      : (utilityAction?.hideButton ?? false)
  const utilityActionToRun = hideUtilityButton ? undefined : utilityAction

  const resolvedUtilityVariant =
    typeof utilityActionToRun?.variant === 'function'
      ? utilityActionToRun.variant(item)
      : (utilityAction?.variant ?? 'danger')

  const resolvedUtilityAriaLabel = utilityActionToRun
    ? resolveTextValue(
        utilityActionToRun.ariaLabel ?? utilityActionToRun.label,
        item
      )
    : 'Delete'

  const resolvedUtilityDisabled = utilityAction?.disabled?.(item) ?? false
  const resolvedUtilityExits = utilityAction
    ? typeof utilityAction.exits === 'function'
      ? utilityAction.exits(item)
      : (utilityAction.exits ?? false)
    : true

  const defaultDeleteIcon =
    theme.id === 'princess' ? (
      <img
        src={princessDeleteIcon}
        alt="Delete"
        className="h-6 w-6 object-contain"
      />
    ) : (
      <span>🗑️</span>
    )

  const resolvedUtilityIcon = utilityActionToRun
    ? resolveValue(utilityActionToRun.icon ?? defaultDeleteIcon, item) ||
      defaultDeleteIcon
    : defaultDeleteIcon

  const handleUtilityAction = () => {
    const runAction = () => {
      if (utilityActionToRun) {
        runActionSafely('utility action', () =>
          utilityActionToRun.onClick(item)
        )
        return
      }
      runActionSafely('delete action', () => onDelete(item))
    }

    if (resolvedUtilityExits) {
      setIsExiting(true)
      setTimeout(runAction, 400)
      return
    }

    runAction()
  }

  const itemKey = getKey ? getKey(item) : `${index}`
  const isInlineEditing = editingId !== undefined && editingId === itemKey

  useEffect(() => {
    if (!isInlineEditing) return
    cardRef.current?.scrollIntoView({ block: 'start', behavior: 'smooth' })
  }, [isInlineEditing])

  const rowStyle: CSSProperties = isItemHighlighted
    ? {
        ...rowBaseStyle,
        background: `linear-gradient(135deg, ${theme.colors.primary}, ${theme.colors.secondary})`,
        color: isDarkTheme ? '#000' : '#FFF',
      }
    : {
        ...rowBaseStyle,
        backgroundColor: theme.colors.surface,
        color: theme.colors.text,
      }

  const starCount = getStarCount?.(item)
  const hidePrimaryButton =
    typeof primaryAction.hideButton === 'function'
      ? primaryAction.hideButton(item)
      : (primaryAction.hideButton ?? false)
  const hideEditButton =
    typeof hideEdit === 'function' ? hideEdit(item) : (hideEdit ?? false)

  const inlineEditStyle: CSSProperties = {
    ...rowBaseStyle,
    background: theme.colors.surface,
    border: `3px solid ${theme.colors.primary}`,
    boxShadow: `0 10px 20px -5px ${theme.colors.primary}20`,
    color: theme.colors.text,
    boxSizing: 'border-box',
  }

  return (
    <div
      ref={cardRef}
      key={itemKey}
      className={`${isInlineEditing ? '' : 'whimsical-card'} flex flex-col ${isExiting ? 'whimsical-card-exiting' : ''}`}
      style={{
        ...(isInlineEditing ? inlineEditStyle : rowStyle),
        gap: `${uiTokens.panelStackGap}px`,
      }}
    >
      {/* Inline edit mode — replaces normal content + actions */}
      {isInlineEditing && renderInlineEdit ? (
        <div className="flex min-w-0 flex-col">{renderInlineEdit(item)}</div>
      ) : (
        <>
          {/* Header / Content */}
          <div
            className="flex flex-col"
            style={{ fontFamily: theme.fonts.heading }}
          >
            {renderItem(item)}
          </div>

          {/* Star Field (if star count is provided) */}
          {starCount !== undefined && <StarDisplay count={starCount} />}

          {/* Action Buttons - Horizontal row with spacing */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: `${uiTokens.actionRowGap}px`,
              justifyContent: hidePrimaryButton ? 'flex-end' : undefined,
            }}
          >
            {/* Primary Action - takes most space */}
            {!hidePrimaryButton && (
              <button
                type="button"
                onClick={() =>
                  runActionSafely('primary action', () =>
                    primaryAction.onClick(item)
                  )
                }
                disabled={primaryDisabled}
                className="whimsical-btn flex-1 disabled:opacity-60"
                aria-label={resolveTextValue(
                  primaryAction.ariaLabel ?? primaryAction.label,
                  item
                )}
                style={{
                  ...actionBaseStyle,
                  ...getActionStyle(
                    typeof primaryAction.variant === 'function'
                      ? primaryAction.variant(item)
                      : primaryAction.variant
                  ),
                  position: 'relative',
                  overflow: 'hidden',
                }}
              >
                {resolveValue(primaryAction.icon ?? '⭐', item)}
                {(typeof primaryAction.showLabel === 'function'
                  ? primaryAction.showLabel(item)
                  : primaryAction.showLabel) === false ? null : (
                  <span>{resolveValue(primaryAction.label, item)}</span>
                )}
              </button>
            )}

            {/* Edit Button - optional */}
            {!hideEditButton && onEdit && (
              <button
                type="button"
                onClick={() =>
                  runActionSafely('edit action', () => onEdit(item))
                }
                className="whimsical-btn whimsical-btn-utility"
                aria-label="Edit"
                style={{
                  ...actionBaseStyle,
                  ...getActionStyle('neutral'),
                  width: `${uiTokens.listUtilityActionWidth}px`,
                  minWidth: `${uiTokens.listUtilityActionWidth}px`,
                  padding: 0,
                }}
              >
                {theme.id === 'princess' ? (
                  <img
                    src={princessEditIcon}
                    alt="Edit"
                    className="h-6 w-6 object-contain"
                  />
                ) : (
                  <span>✏️</span>
                )}
              </button>
            )}

            {/* Delete Button */}
            {!hideUtilityButton && (
              <button
                type="button"
                onClick={handleUtilityAction}
                disabled={resolvedUtilityDisabled}
                className={`whimsical-btn whimsical-btn-utility disabled:opacity-60 ${resolvedUtilityVariant === 'danger' ? 'whimsical-btn-delete' : ''}`}
                aria-label={resolvedUtilityAriaLabel}
                style={{
                  ...actionBaseStyle,
                  ...getActionStyle(resolvedUtilityVariant),
                  width: `${uiTokens.listUtilityActionWidth}px`,
                  minWidth: `${uiTokens.listUtilityActionWidth}px`,
                  padding: 0,
                }}
              >
                {resolvedUtilityIcon}
              </button>
            )}
          </div>
        </>
      )}
    </div>
  )
}

const StandardActionList = <T,>({
  theme,
  items,
  renderItem,
  primaryAction,
  onEdit,
  onDelete,
  utilityAction,
  addLabel,
  onAdd,
  addDisabled = false,
  isLoading = false,
  emptyState,
  getKey,
  isHighlighted,
  getStarCount,
  hideEdit,
  editingId,
  renderInlineEdit,
  inlineNewRow,
  frameInlineNewRow = true,
  hideAdd = false,
}: StandardActionListProps<T>) => {
  const isDarkTheme = theme.id === 'space'

  // Inject CSS animations on mount
  useEffect(() => {
    injectWhimsicalStyles()
  }, [])

  // Vibrant gradient shadow based on theme
  const cardShadow = `
    0 10px 20px -5px ${theme.colors.primary}30,
    0 6px 0 ${theme.colors.surface}66 inset
  `

  const actionBaseStyle = getStandardActionBaseStyle(theme)

  const rowBaseStyle: CSSProperties = {
    borderRadius: `${uiTokens.listItemRadius}px`,
    padding: `${uiTokens.listItemPadding}px`,
    border: `${uiTokens.listItemBorderWidth}px solid ${theme.colors.surface}`,
    boxShadow: cardShadow,
    background: `linear-gradient(145deg, ${theme.colors.surface} 0%, ${theme.colors.bg} 100%)`,
  }

  const getActionStyle = (
    variant?: ActionConfig<T>['variant']
  ): CSSProperties =>
    getStandardActionVariantStyle(
      theme,
      typeof variant === 'function' ? 'primary' : variant
    )

  return (
    <div className="flex flex-col" style={{ width: '100%' }}>
      {isLoading ? (
        <div
          className="rounded-3xl p-6 text-center text-lg font-bold"
          style={{
            backgroundColor: `${theme.colors.primary}20`,
            color: theme.colors.text,
          }}
        >
          Loading...
        </div>
      ) : (
        <div
          className="flex flex-col"
          style={{ gap: `${uiTokens.panelStackGap}px` }}
        >
          {items.length === 0
            ? (emptyState ?? (
                <div
                  className="rounded-3xl p-6 text-center text-lg font-bold"
                  style={{
                    backgroundColor: `${theme.colors.primary}20`,
                    color: theme.colors.text,
                  }}
                >
                  Nothing here yet.
                </div>
              ))
            : items.map((item, index) => {
                const isItemHighlighted = isHighlighted?.(item) ?? false
                const primaryDisabled = primaryAction.disabled?.(item) ?? false

                return (
                  <ActionCard
                    key={getKey ? getKey(item) : `${index}`}
                    item={item}
                    index={index}
                    theme={theme}
                    isDarkTheme={isDarkTheme}
                    rowBaseStyle={rowBaseStyle}
                    isItemHighlighted={isItemHighlighted}
                    renderItem={renderItem}
                    primaryAction={primaryAction}
                    primaryDisabled={primaryDisabled}
                    onEdit={onEdit}
                    onDelete={onDelete}
                    utilityAction={utilityAction}
                    getActionStyle={getActionStyle}
                    actionBaseStyle={actionBaseStyle}
                    getKey={getKey}
                    getStarCount={getStarCount}
                    hideEdit={hideEdit}
                    editingId={editingId}
                    renderInlineEdit={renderInlineEdit}
                  />
                )
              })}

          {/* Inline New Row — shown in place of the Add button card */}
          {inlineNewRow && !frameInlineNewRow ? (
            inlineNewRow
          ) : inlineNewRow ? (
            <div
              className="flex flex-col"
              style={{
                ...rowBaseStyle,
                background: theme.colors.surface,
                border: `3px solid ${theme.colors.primary}`,
                boxShadow: `0 10px 20px -5px ${theme.colors.primary}20`,
                gap: `${uiTokens.panelStackGap}px`,
              }}
            >
              {inlineNewRow}
            </div>
          ) : hideAdd ? null : (
            /* Add Button Card */
            <div
              className="whimsical-card flex flex-col"
              style={{
                ...rowBaseStyle,
                backgroundColor: theme.colors.surface,
                border: `4px dashed ${theme.colors.primary}`,
                boxShadow: `0 10px 20px -5px ${theme.colors.primary}20`,
                background: theme.colors.surface,
              }}
            >
              <button
                type="button"
                onClick={() => runActionSafely('add action', onAdd)}
                disabled={addDisabled}
                className="whimsical-btn flex w-full items-center justify-center text-xl font-bold disabled:opacity-60"
                style={{
                  color: theme.colors.primary,
                  minHeight: `${uiTokens.actionButtonHeight}px`,
                  fontFamily: theme.fonts.heading,
                  cursor: addDisabled ? 'not-allowed' : 'pointer',
                  background: 'transparent',
                  border: 'none',
                  gap: `${uiTokens.actionContentGap}px`,
                }}
              >
                <span>➕</span> {addLabel}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default StandardActionList

types.body:
CSSProperties & {
  '--star-rot': string
}

modules.text:
import { useEffect, useState, type CSSProperties } from 'react'
import type { Theme } from '../../contexts/ThemeContext'
import StepperButton, { getStepperEdgePositionStyle } from './StepperButton'
import { uiTokens } from '../../tokens'
import starSvgUrl from '../../assets/global/star.svg'
import starNegativeSvgUrl from '../../assets/global/star-negative.svg'

const STAR_DISPLAY_STYLES_ID = 'star-display-styles'
const injectStarDisplayStyles = () => {
  if (document.getElementById(STAR_DISPLAY_STYLES_ID)) return
  const style = document.createElement('style')
  style.id = STAR_DISPLAY_STYLES_ID
  style.textContent = `
    @keyframes star-pop-in {
      0% { transform: scale(0) rotate(-180deg); opacity: 0; }
      60% { transform: scale(1.3) rotate(10deg); opacity: 1; }
      100% { transform: scale(1) rotate(var(--star-rot, 0deg)); opacity: 1; }
    }
    @keyframes star-pop-out {
      0% { transform: scale(1) rotate(var(--star-rot, 0deg)); opacity: 1; }
      100% { transform: scale(0) rotate(45deg); opacity: 0; }
    }
  `
  document.head.appendChild(style)
}

export type StarDisplayProps = {
  count: number
  animate?: boolean
  style?: CSSProperties
  className?: string
  emptyContent?: React.ReactNode
  editable?: boolean
  onChange?: (value: number) => void
  min?: number
  max?: number
  theme?: Theme
}

const CONTROLS_DELAY_MS = 550
const CONTROL_ROW_WIDTH = uiTokens.controlRowWidth

type DensityClass = 'low' | 'medium'

const getDensityClass = (count: number): DensityClass => {
  if (count > 24) return 'medium'
  return 'low'
}

const DENSITY_SIZES = {
  low: { width: 32, gap: 8 },
  medium: { width: 20, gap: 4 },
} satisfies Record<DensityClass, { width: number; gap: number }>

type StarIconProps = {
  size: number
  scale?: number
  rotation?: number
  animationDelay?: number
  animate?: boolean
  assetUrl?: string
  style?: CSSProperties
  className?: string
}

type StarIconStyle = CSSProperties & {
  '--star-rot': string
}

const StarIcon = ({
  size,
  scale = 1,
  rotation = 0,
  animationDelay = 0,
  animate = true,
  assetUrl = starSvgUrl,
  style,
  className,
}: StarIconProps) => {
  const finalSize = size * scale

  const starStyle: StarIconStyle = {
    width: finalSize,
    height: finalSize,
    flexShrink: 0,
    filter: 'drop-shadow(0 2px 0 rgba(0,0,0,0.1))',
    '--star-rot': `${rotation}deg`,
    ...(animate
      ? {
          animation:
            'star-pop-in 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards',
          animationDelay: `${animationDelay}s`,
        }
      : {}),
    ...style,
  }

  return (
    <img
      src={assetUrl}
      alt=""
      className={className}
      style={starStyle}
      aria-hidden="true"
    />
  )
}

const FieldVariant = ({
  count,
  animate = true,
  emptyContent,
  style,
  className,
}: StarDisplayProps) => {
  const displayMagnitude = Math.abs(count)
  const densityClass = getDensityClass(displayMagnitude)
  const { width, gap } = DENSITY_SIZES[densityClass]
  const assetUrl = count < 0 ? starNegativeSvgUrl : starSvgUrl

  // Track previous count for animation direction
  const [prevCount, setPrevCount] = useState(displayMagnitude)
  const [animatingOut, setAnimatingOut] = useState<number[]>([])

  useEffect(() => {
    if (displayMagnitude < prevCount && animate) {
      const removedCount = prevCount - displayMagnitude
      const removedIndices = Array.from(
        { length: removedCount },
        (_, i) => displayMagnitude + i
      )
      setAnimatingOut(removedIndices)
      const timer = setTimeout(() => {
        setAnimatingOut([])
        setPrevCount(displayMagnitude)
      }, 300)
      return () => clearTimeout(timer)
    } else {
      setPrevCount(displayMagnitude)
    }
  }, [displayMagnitude, prevCount, animate])

  const containerStyle: CSSProperties = {
    background: '#f1f5f9',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    padding: '12px',
    minHeight: `${uiTokens.listActionHeight}px`,
    border: '2px dashed #cbd5e1',
    display: 'flex',
    flexWrap: 'wrap',
    alignItems: 'center',
    justifyContent: 'center',
    gap: `${gap}px`,
    ...style,
  }

  if (displayMagnitude === 0 && animatingOut.length === 0) {
    return (
      <div style={containerStyle} className={className}>
        {emptyContent !== undefined ? (
          emptyContent
        ) : (
          <span
            style={{
              opacity: 0.5,
              fontStyle: 'italic',
              color: '#64748b',
              fontSize: '0.9rem',
            }}
          >
            No stars yet...
          </span>
        )}
      </div>
    )
  }

  const displayCount = Math.max(displayMagnitude, prevCount)
  const stars = Array.from({ length: displayCount })

  return (
    <div style={containerStyle} className={className}>
      {stars.map((_, i) => {
        const rot = ((i * 33) % 40) - 20
        const isExiting = animatingOut.includes(i)

        return (
          <StarIcon
            key={i}
            size={width}
            assetUrl={assetUrl}
            rotation={rot}
            animationDelay={animate && !isExiting ? i * 0.03 : 0}
            animate={animate && !isExiting}
            style={
              isExiting
                ? {
                    animation: 'star-pop-out 0.3s ease-out forwards',
                  }
                : undefined
            }
          />
        )
      })}
    </div>
  )
}

const CompactCountVariant = ({
  count,
  style,
  className,
  theme,
}: StarDisplayProps) => {
  const assetUrl = count < 0 ? starNegativeSvgUrl : starSvgUrl

  const containerStyle: CSSProperties = {
    background: '#f1f5f9',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    padding: '12px',
    minHeight: `${uiTokens.listActionHeight}px`,
    border: '2px dashed #cbd5e1',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    ...style,
  }

  return (
    <div
      style={containerStyle}
      className={className}
      role="img"
      aria-label={`${count} stars`}
    >
      <span
        style={{
          color: theme?.colors.primary ?? '#EC4899',
          fontFamily: theme?.fonts.heading,
          fontSize: '2rem',
          fontWeight: 900,
          lineHeight: 1,
        }}
      >
        {count}
      </span>
      <StarIcon size={38} assetUrl={assetUrl} animate={false} />
    </div>
  )
}

const shouldUseCompactValue = (count: number) => Math.abs(count) > 10

const renderEditableValue = ({
  count,
  animate,
  theme,
  className,
}: {
  count: number
  animate: boolean
  theme: Theme
  className?: string
}) => {
  const valueStyle: CSSProperties = {
    width: '100%',
    boxSizing: 'border-box',
  }

  return shouldUseCompactValue(count) ? (
    <CompactCountVariant
      count={count}
      theme={theme}
      className={className}
      style={valueStyle}
    />
  ) : (
    <FieldVariant
      count={count}
      animate={animate}
      className={className}
      style={valueStyle}
    />
  )
}

const StarDisplay = ({
  count,
  animate = true,
  style,
  className,
  emptyContent,
  editable = false,
  onChange,
  min = 1,
  max,
  theme,
}: StarDisplayProps) => {
  const [controlsVisible, setControlsVisible] = useState(false)

  useEffect(() => {
    injectStarDisplayStyles()
  }, [])

  useEffect(() => {
    if (!editable) {
      setControlsVisible(false)
      return
    }
    const timer = setTimeout(() => setControlsVisible(true), CONTROLS_DELAY_MS)
    return () => clearTimeout(timer)
  }, [editable])

  const handleDecrement = () => {
    if (onChange && count > min) onChange(count - 1)
  }

  const handleIncrement = () => {
    if (onChange && (max === undefined || count < max)) onChange(count + 1)
  }

  const showControls = editable && controlsVisible

  if (editable && theme) {
    return (
      <div
        style={{
          position: 'relative',
          width: `${CONTROL_ROW_WIDTH}px`,
          maxWidth: '100%',
          overflow: 'visible',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          ...style,
        }}
        className={className}
      >
        <div
          style={{
            ...getStepperEdgePositionStyle('prev'),
            opacity: showControls ? 1 : 0,
            transition: 'opacity 0.3s ease',
            pointerEvents: showControls ? 'auto' : 'none',
            zIndex: showControls ? 3 : 1,
          }}
        >
          <StepperButton
            theme={theme}
            direction="prev"
            onClick={handleDecrement}
            disabled={count <= min}
            ariaLabel="Decrease star value"
            style={{ position: 'relative', zIndex: 3 }}
          />
        </div>

        <div style={{ width: '100%', minWidth: 0 }}>
          {renderEditableValue({ count, animate, theme })}
        </div>

        <div
          style={{
            ...getStepperEdgePositionStyle('next'),
            opacity: showControls ? 1 : 0,
            transition: 'opacity 0.3s ease',
            pointerEvents: showControls ? 'auto' : 'none',
            zIndex: showControls ? 3 : 1,
          }}
        >
          <StepperButton
            theme={theme}
            direction="next"
            onClick={handleIncrement}
            disabled={max !== undefined && count >= max}
            ariaLabel="Increase star value"
            style={{ position: 'relative', zIndex: 3 }}
          />
        </div>
      </div>
    )
  }

  return (
    <FieldVariant
      count={count}
      animate={animate}
      emptyContent={emptyContent}
      style={style}
      className={className}
    />
  )
}

export default StarDisplay

