import { useEffect, useState, type CSSProperties } from 'react'
import type { Theme } from '../../contexts/ThemeContext'
import StepperButton, { getStepperEdgePositionStyle } from './StepperButton'
import { uiTokens } from '../../tokens'
import starSvgUrl from '../../assets/global/star.svg'
import starNegativeSvgUrl from '../../assets/global/star-negative.svg'

const STAR_DISPLAY_STYLES_ID = 'star-display-styles'
const injectStarDisplayStyles = () => {
  if (document.getElementById(STAR_DISPLAY_STYLES_ID)) return
  const style = document.createElement('style')
  style.id = STAR_DISPLAY_STYLES_ID
  style.textContent = `
    @keyframes star-pop-in {
      0% { transform: scale(0) rotate(-180deg); opacity: 0; }
      60% { transform: scale(1.3) rotate(10deg); opacity: 1; }
      100% { transform: scale(1) rotate(var(--star-rot, 0deg)); opacity: 1; }
    }
    @keyframes star-pop-out {
      0% { transform: scale(1) rotate(var(--star-rot, 0deg)); opacity: 1; }
      100% { transform: scale(0) rotate(45deg); opacity: 0; }
    }
  `
  document.head.appendChild(style)
}

export type StarDisplayProps = {
  count: number
  animate?: boolean
  style?: CSSProperties
  className?: string
  emptyContent?: React.ReactNode
  editable?: boolean
  onChange?: (value: number) => void
  min?: number
  max?: number
  theme?: Theme
}

const CONTROLS_DELAY_MS = 550
const CONTROL_ROW_WIDTH = uiTokens.controlRowWidth

type DensityClass = 'low' | 'medium'

const getDensityClass = (count: number): DensityClass => {
  if (count > 24) return 'medium'
  return 'low'
}

const DENSITY_SIZES = {
  low: { width: 32, gap: 8 },
  medium: { width: 20, gap: 4 },
} satisfies Record<DensityClass, { width: number; gap: number }>

type StarIconProps = {
  size: number
  scale?: number
  rotation?: number
  animationDelay?: number
  animate?: boolean
  assetUrl?: string
  style?: CSSProperties
  className?: string
}

type StarIconStyle = CSSProperties & {
  '--star-rot': string
}

const StarIcon = ({
  size,
  scale = 1,
  rotation = 0,
  animationDelay = 0,
  animate = true,
  assetUrl = starSvgUrl,
  style,
  className,
}: StarIconProps) => {
  const finalSize = size * scale

  const starStyle: StarIconStyle = {
    width: finalSize,
    height: finalSize,
    flexShrink: 0,
    filter: 'drop-shadow(0 2px 0 rgba(0,0,0,0.1))',
    '--star-rot': `${rotation}deg`,
    ...(animate
      ? {
          animation:
            'star-pop-in 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards',
          animationDelay: `${animationDelay}s`,
        }
      : {}),
    ...style,
  }

  return (
    <img
      src={assetUrl}
      alt=""
      className={className}
      style={starStyle}
      aria-hidden="true"
    />
  )
}

const FieldVariant = ({
  count,
  animate = true,
  emptyContent,
  style,
  className,
}: StarDisplayProps) => {
  const displayMagnitude = Math.abs(count)
  const densityClass = getDensityClass(displayMagnitude)
  const { width, gap } = DENSITY_SIZES[densityClass]
  const assetUrl = count < 0 ? starNegativeSvgUrl : starSvgUrl

  // Track previous count for animation direction
  const [prevCount, setPrevCount] = useState(displayMagnitude)
  const [animatingOut, setAnimatingOut] = useState<number[]>([])

  useEffect(() => {
    if (displayMagnitude < prevCount && animate) {
      const removedCount = prevCount - displayMagnitude
      const removedIndices = Array.from(
        { length: removedCount },
        (_, i) => displayMagnitude + i
      )
      setAnimatingOut(removedIndices)
      const timer = setTimeout(() => {
        setAnimatingOut([])
        setPrevCount(displayMagnitude)
      }, 300)
      return () => clearTimeout(timer)
    } else {
      setPrevCount(displayMagnitude)
    }
  }, [displayMagnitude, prevCount, animate])

  const containerStyle: CSSProperties = {
    background: '#f1f5f9',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    padding: '12px',
    minHeight: `${uiTokens.listActionHeight}px`,
    border: '2px dashed #cbd5e1',
    display: 'flex',
    flexWrap: 'wrap',
    alignItems: 'center',
    justifyContent: 'center',
    gap: `${gap}px`,
    ...style,
  }

  if (displayMagnitude === 0 && animatingOut.length === 0) {
    return (
      <div style={containerStyle} className={className}>
        {emptyContent !== undefined ? (
          emptyContent
        ) : (
          <span
            style={{
              opacity: 0.5,
              fontStyle: 'italic',
              color: '#64748b',
              fontSize: '0.9rem',
            }}
          >
            No stars yet...
          </span>
        )}
      </div>
    )
  }

  const displayCount = Math.max(displayMagnitude, prevCount)
  const stars = Array.from({ length: displayCount })

  return (
    <div style={containerStyle} className={className}>
      {stars.map((_, i) => {
        const rot = ((i * 33) % 40) - 20
        const isExiting = animatingOut.includes(i)

        return (
          <StarIcon
            key={i}
            size={width}
            assetUrl={assetUrl}
            rotation={rot}
            animationDelay={animate && !isExiting ? i * 0.03 : 0}
            animate={animate && !isExiting}
            style={
              isExiting
                ? {
                    animation: 'star-pop-out 0.3s ease-out forwards',
                  }
                : undefined
            }
          />
        )
      })}
    </div>
  )
}

const CompactCountVariant = ({
  count,
  style,
  className,
  theme,
}: StarDisplayProps) => {
  const assetUrl = count < 0 ? starNegativeSvgUrl : starSvgUrl

  const containerStyle: CSSProperties = {
    background: '#f1f5f9',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    padding: '12px',
    minHeight: `${uiTokens.listActionHeight}px`,
    border: '2px dashed #cbd5e1',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    ...style,
  }

  return (
    <div
      style={containerStyle}
      className={className}
      role="img"
      aria-label={`${count} stars`}
    >
      <span
        style={{
          color: theme?.colors.primary ?? '#EC4899',
          fontFamily: theme?.fonts.heading,
          fontSize: '2rem',
          fontWeight: 900,
          lineHeight: 1,
        }}
      >
        {count}
      </span>
      <StarIcon size={38} assetUrl={assetUrl} animate={false} />
    </div>
  )
}

const shouldUseCompactValue = (count: number) => Math.abs(count) > 10

const renderEditableValue = ({
  count,
  animate,
  theme,
  className,
}: {
  count: number
  animate: boolean
  theme: Theme
  className?: string
}) => {
  const valueStyle: CSSProperties = {
    width: '100%',
    boxSizing: 'border-box',
  }

  return shouldUseCompactValue(count) ? (
    <CompactCountVariant
      count={count}
      theme={theme}
      className={className}
      style={valueStyle}
    />
  ) : (
    <FieldVariant
      count={count}
      animate={animate}
      className={className}
      style={valueStyle}
    />
  )
}

const StarDisplay = ({
  count,
  animate = true,
  style,
  className,
  emptyContent,
  editable = false,
  onChange,
  min = 1,
  max,
  theme,
}: StarDisplayProps) => {
  const [controlsVisible, setControlsVisible] = useState(false)

  useEffect(() => {
    injectStarDisplayStyles()
  }, [])

  useEffect(() => {
    if (!editable) {
      setControlsVisible(false)
      return
    }
    const timer = setTimeout(() => setControlsVisible(true), CONTROLS_DELAY_MS)
    return () => clearTimeout(timer)
  }, [editable])

  const handleDecrement = () => {
    if (onChange && count > min) onChange(count - 1)
  }

  const handleIncrement = () => {
    if (onChange && (max === undefined || count < max)) onChange(count + 1)
  }

  const showControls = editable && controlsVisible

  if (editable && theme) {
    return (
      <div
        style={{
          position: 'relative',
          width: `${CONTROL_ROW_WIDTH}px`,
          maxWidth: '100%',
          overflow: 'visible',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          ...style,
        }}
        className={className}
      >
        <div
          style={{
            ...getStepperEdgePositionStyle('prev'),
            opacity: showControls ? 1 : 0,
            transition: 'opacity 0.3s ease',
            pointerEvents: showControls ? 'auto' : 'none',
            zIndex: showControls ? 3 : 1,
          }}
        >
          <StepperButton
            theme={theme}
            direction="prev"
            onClick={handleDecrement}
            disabled={count <= min}
            ariaLabel="Decrease star value"
            style={{ position: 'relative', zIndex: 3 }}
          />
        </div>

        <div style={{ width: '100%', minWidth: 0 }}>
          {renderEditableValue({ count, animate, theme })}
        </div>

        <div
          style={{
            ...getStepperEdgePositionStyle('next'),
            opacity: showControls ? 1 : 0,
            transition: 'opacity 0.3s ease',
            pointerEvents: showControls ? 'auto' : 'none',
            zIndex: showControls ? 3 : 1,
          }}
        >
          <StepperButton
            theme={theme}
            direction="next"
            onClick={handleIncrement}
            disabled={max !== undefined && count >= max}
            ariaLabel="Increase star value"
            style={{ position: 'relative', zIndex: 3 }}
          />
        </div>
      </div>
    )
  }

  return (
    <FieldVariant
      count={count}
      animate={animate}
      emptyContent={emptyContent}
      style={style}
      className={className}
    />
  )
}

export default StarDisplay

