            ? state.manageDinnerTimerStartedAt
            : task.manageDinnerTimerStartedAt,
        manageDinnerCompletedAt:
          state.manageDinnerCompletedAt !== undefined
            ? state.manageDinnerCompletedAt
            : task.manageDinnerCompletedAt,
      }
    case 'math':
      return {
