          const lastActive = getLastActive(state)
          if (lastActive && now - lastActive >= MANAGE_STATUS_RESET_MS) {
            if (next === prev) next = { ...prev }
            delete next[item.id]
          }
        }
        return next
      })
    }, 60000)
    return () => clearInterval(interval)
  }, [enabled, getLastActive, items, setEphemeral])
}

