}

const renderTitle = (
  deps: UnifiedChoreDeps,
  item: UnifiedChoreItem,
  titleLabel: string
) =>
  deps.mode === 'manage' ? (
    <ActionTextInput
      theme={deps.theme}
      label={titleLabel}
      value={deps.titleDrafts?.[item.id] ?? item.title}
      onChange={(value) => deps.onSetTitleDraft?.(item.id, value)}
