              theme={deps.theme}
              value={item.isRepeating}
              onChange={(value) =>
                deps.onUpdateTaskField?.(item.id, { isRepeating: value })
              }
              showLabel={false}
              showFeedback={false}
            />
          </div>
          {!showImageRewardFrame && (
            <div className="flex flex-col items-center" style={{ gap: '0px' }}>
              <StarDisplay
                theme={deps.theme}
                count={item.starValue}
                editable
                onChange={(value) =>
                  deps.onUpdateTaskField?.(item.id, { starValue: value || 1 })
                }
                min={1}
                max={3}
              />
            </div>
          )}
        </>
      )}
    </>
  )
}

const renderStandardChoreImageRewardFrame = (
  image: string,
  title: string,
  starValue: number,
  theme: UnifiedChoreDeps['theme']
) => {
  const frameStyle: CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    width: '100%',
    minHeight: '116px',
    padding: '10px',
    borderRadius: `${uiTokens.surfaceRadius}px`,
    border: `3px dashed ${theme.colors.primary}55`,
    background: `${theme.colors.bg}88`,
    overflow: 'visible',
    boxSizing: 'border-box',
  }

  const imageLaneStyle: CSSProperties = {
    flex: '0 0 38%',
    minWidth: '96px',
    maxWidth: '152px',
    marginRight: '-26px',
    position: 'relative',
    zIndex: 2,
  }

  const imageFrameStyle: CSSProperties = {
    width: '100%',
    aspectRatio: '1',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'visible',
  }

  const starLaneStyle: CSSProperties = {
    flex: '1 1 66%',
    minWidth: 0,
    position: 'relative',
    zIndex: 1,
  }

  return (
    <div style={frameStyle}>
      <div style={imageLaneStyle}>
        <div style={imageFrameStyle}>
          <img
            src={image}
            alt={`${title} chore`}
            style={{
              width: '112%',
              height: '112%',
              objectFit: 'contain',
              display: 'block',
            }}
          />
        </div>
      </div>

      <div style={starLaneStyle}>
        <StarDisplay
          count={starValue}
          animate={false}
          style={{
            width: '100%',
            minHeight: '84px',
            padding: '10px 10px 10px 4px',
            background: 'transparent',
            border: '0',
            boxSizing: 'border-box',
          }}
        />
      </div>
    </div>
  )
}

